	(2, 'Mohammed Al-Rashid', 'mohammed.alrashid@example.com', '555-5678', 'Admission Question', 'I am interested in enrolling my daughter in Grade 3. What documents are required for admission and what is the application deadline?', '2025-07-02 17:18:04', '2025-07-02 17:18:04'),
	(3, 'Emily Chen', 'emily.chen@example.com', '555-8765', 'School Tour Request', 'I would like to schedule a school tour for next week. Are there any available time slots on Tuesday or Wednesday afternoon?', '2025-07-02 17:18:04', '2025-07-02 17:18:04');
