	(75, 'content', 'Welcome to Saud International School! We\'re thrilled to have you join our diverse community where we provide a challenging and inspiring educational environment. Together, we\'ll explore our internationally recognized curriculum enhanced with cutting-edge technology and enriching extra-curricular activities designed to help you thrive and discover your potential.', 1, 'App\\Models\\LanguageKey', 38, '2025-06-30 21:35:02', '2025-06-30 21:35:02'),
	(76, 'content', 'مرحباً بكم في مدارس سعود العالمية! نحن متحمسون لانضمامكم إلى مجتمعنا المتنوع حيث نوفر بيئة تعليمية تحدي وملهمة. معاً، سنستكشف منهجنا المعترف به دولياً والمعزز بأحدث التقنيات والأنشطة اللامنهجية الإثرائية المصممة لمساعدتكم على الازدهار واكتشاف إمكاناتكم.', 2, 'App\\Models\\LanguageKey', 38, '2025-06-30 21:35:02', '2025-06-30 21:35:02'),
	(77, 'content', 'Welcome to Saud international schools', 1, 'App\\Models\\LanguageKey', 39, '2025-06-30 21:35:02', '2025-06-30 21:35:02'),
