	(411, 'title', 'School Visits', 1, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(412, 'title', 'زيارات المدرسة', 2, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(413, 'description', 'Book a visit to explore our school facilities and programs', 1, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(414, 'description', 'احجز زيارة لاستكشاف مرافق وبرامج مدرستنا', 2, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(415, 'content', 'We welcome you to visit our school and discover what makes us special. Choose from our available visit services and book a convenient time for your tour.', 1, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(416, 'content', 'نرحب بكم لزيارة مدرستنا واكتشاف ما يجعلنا مميزين. اختر من خدمات الزيارة المتاحة واحجز وقتاً مناسباً لجولتك.', 2, 'App\\Models\\Page', 5, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(417, 'title', 'Student Inquiries', 1, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(418, 'title', 'استفسارات الطلاب', 2, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(419, 'description', 'Submit your inquiry about admissions and school programs', 1, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(420, 'description', 'قدم استفسارك حول القبول وبرامج المدرسة', 2, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(421, 'content', 'Have questions about our school? We\'re here to help! Please fill out the form below with your inquiry about admissions, programs, or any other questions you may have. Our admissions team will get back to you as soon as possible.', 1, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(422, 'content', 'لديك أسئلة حول مدرستنا؟ نحن هنا للمساعدة! يرجى ملء النموذج أدناه باستفسارك حول القبول أو البرامج أو أي أسئلة أخرى قد تكون لديك. سيتواصل معك فريق القبول في أقرب وقت ممكن.', 2, 'App\\Models\\Page', 6, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(423, 'title', 'Contact Us', 1, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(424, 'title', 'اتصل بنا', 2, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(425, 'description', 'Get in touch with us for any questions or information', 1, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(426, 'description', 'تواصل معنا لأي أسئلة أو معلومات', 2, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(427, 'content', 'We would love to hear from you! Please feel free to reach out to us with any questions, comments, or inquiries. Our team is here to help and will respond to your message as soon as possible.', 1, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(428, 'content', 'نحن نحب أن نسمع منك! لا تتردد في التواصل معنا لأي أسئلة أو تعليقات أو استفسارات. فريقنا هنا للمساعدة وسيرد على رسالتك في أقرب وقت ممكن.', 2, 'App\\Models\\Page', 7, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(429, 'title', 'Career Opportunities', 1, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(430, 'title', 'الفرص الوظيفية', 2, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(431, 'description', 'Join our team of dedicated educators and staff', 1, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(432, 'description', 'انضم إلى فريقنا من المعلمين والموظفين المتفانين', 2, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(433, 'content', 'Discover exciting career opportunities at Saud International Schools. We are always looking for passionate educators and dedicated professionals to join our team and help shape the future of education.', 1, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(434, 'content', 'اكتشف الفرص الوظيفية المثيرة في مدارس سعود العالمية. نحن نبحث دائماً عن معلمين متحمسين ومهنيين متفانين للانضمام إلى فريقنا والمساعدة في تشكيل مستقبل التعليم.', 2, 'App\\Models\\Page', 8, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(435, 'title', 'School Policies', 1, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:38:37'),
	(436, 'title', 'سياسات المدرسة', 2, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:39:22'),
	(437, 'description', 'Clear and comprehensive school policies that promote a safe, inclusive, and respectful learning environment while supporting academic integrity and student well-being.', 1, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:38:37'),
	(438, 'description', 'سياسات مدرسية واضحة وشاملة تعمل على تعزيز بيئة تعليمية آمنة وشاملة ومحترمة مع دعم النزاهة الأكاديمية ورفاهية الطلاب.', 2, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:39:22'),
	(439, 'content', '<p>Please find below a selection of the most frequently requested school policies. If you would like more details on these policies then please do not hesitate to contact the school.</p>', 1, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:40:46'),
	(440, 'content', '<p>تجدون أدناه مجموعة مختارة من سياسات المدرسة الأكثر طلبًا. لمزيد من التفاصيل حول هذه السياسات، يُرجى التواصل مع المدرسة.</p>', 2, 'App\\Models\\Page', 9, '2025-06-30 21:35:04', '2025-07-26 15:41:20'),
	(441, 'title', 'Page Not Found', 1, 'App\\Models\\Page', 10, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
