	(444, 'description', 'لا يمكن العثور على الصفحة التي تبحث عنها', 2, 'App\\Models\\Page', 10, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(445, 'content', 'Sorry, the page you are looking for could not be found. Please check the URL or return to our homepage.', 1, 'App\\Models\\Page', 10, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(446, 'content', 'عذراً، لا يمكن العثور على الصفحة التي تبحث عنها. يرجى التحقق من الرابط أو العودة إلى صفحتنا الرئيسية.', 2, 'App\\Models\\Page', 10, '2025-06-30 21:35:04', '2025-06-30 21:35:04'),
	(447, 'title', 'Meet our dedicated educators', 1, 'App\\Models\\Banner', 1, '2025-06-30 21:37:44', '2025-06-30 21:41:45'),
	(448, 'cta', 'Book a Visit', 1, 'App\\Models\\Banner', 1, '2025-06-30 21:37:44', '2025-06-30 21:37:44'),
	(449, 'title', 'Experience our state-of-the-art facilities and meet our dedicated educators', 1, 'App\\Models\\Media', 1, '2025-06-30 21:37:44', '2025-06-30 21:37:44'),
	(450, 'title', 'اختبر مرافقنا والتق بمعلمينا المتفانين', 2, 'App\\Models\\Banner', 1, '2025-06-30 21:38:28', '2025-06-30 21:41:33'),
	(451, 'cta', 'احجز زيارة', 2, 'App\\Models\\Banner', 1, '2025-06-30 21:38:28', '2025-06-30 21:38:28'),
	(452, 'title', 'Unlock your potential with our education', 1, 'App\\Models\\Banner', 2, '2025-06-30 21:39:22', '2025-06-30 21:40:45'),
