	(455, 'title', 'انضم إلينا واطلق إمكاناتك مع برنامجنا', 2, 'App\\Models\\Banner', 2, '2025-06-30 21:39:44', '2025-06-30 21:41:08'),
	(456, 'cta', 'اطلب الآن', 2, 'App\\Models\\Banner', 2, '2025-06-30 21:39:44', '2025-06-30 21:39:44'),
	(457, 'title', 'Annual Sports Day 2024-2025', 1, 'App\\Models\\Album', 1, '2025-06-30 21:45:03', '2025-06-30 21:45:03'),
	(458, 'description', 'Capturing the spirit of competition and teamwork during our annual sports day celebration. Students from all grades participated in various athletic events, showcasing their talents in track and field, football, basketball, and swimming competitions. The day was filled with excitement, cheering crowds, and memorable moments of victory and sportsmanship. Photos include opening ceremony, individual and team competitions, award ceremonies, and celebration moments with families and teachers.', 1, 'App\\Models\\Album', 1, '2025-06-30 21:45:03', '2025-06-30 21:45:03'),
	(459, 'title', 'Annual Sports Day 2024-2025', 1, 'App\\Models\\Media', 3, '2025-06-30 21:45:03', '2025-06-30 21:45:03'),
	(460, 'description', 'Capturing the spirit of competition and teamwork during our annual sports day celebration. Students from all grades participated in various athletic events, showcasing their talents in track and field, football, basketball, and swimming competitions. The day was filled with excitement, cheering crowds, and memorable moments of victory and sportsmanship. Photos include opening ceremony, individual and team competitions, award ceremonies, and celebration moments with families and teachers.', 1, 'App\\Models\\Media', 3, '2025-06-30 21:45:03', '2025-06-30 21:45:03'),
	(461, 'title', 'International Culture Festival 2025', 1, 'App\\Models\\Album', 2, '2025-06-30 21:46:16', '2025-06-30 21:46:16'),
	(462, 'description', 'A vibrant celebration of diversity at Saud International Schools where students and families from different nationalities came together to share their rich cultural heritage. The festival featured traditional costumes, cultural performances, authentic food stalls, art exhibitions, and interactive workshops. Students presented their countries through dance, music, storytelling, and cultural displays, creating a truly global learning experience that celebrates our multicultural school community.', 1, 'App\\Models\\Album', 2, '2025-06-30 21:46:16', '2025-06-30 21:46:16'),
	(463, 'title', 'International Culture Festival 2025', 1, 'App\\Models\\Media', 4, '2025-06-30 21:46:16', '2025-06-30 21:46:16'),
	(464, 'description', 'A vibrant celebration of diversity at Saud International Schools where students and families from different nationalities came together to share their rich cultural heritage. The festival featured traditional costumes, cultural performances, authentic food stalls, art exhibitions, and interactive workshops. Students presented their countries through dance, music, storytelling, and cultural displays, creating a truly global learning experience that celebrates our multicultural school community.', 1, 'App\\Models\\Media', 4, '2025-06-30 21:46:16', '2025-06-30 21:46:16'),
	(465, 'title', 'يوم الرياضة السنوي 2024-2025', 2, 'App\\Models\\Album', 1, '2025-06-30 21:46:38', '2025-06-30 21:46:38'),
	(466, 'description', 'التقاط روح المنافسة والعمل الجماعي خلال احتفالية يوم الرياضة السنوي. شارك الطلاب من جميع الصفوف في فعاليات رياضية متنوعة، حيث أظهروا مواهبهم في العاب القوى وكرة القدم وكرة السلة ومسابقات السباحة. كان اليوم مليئاً بالإثارة والتشجيع واللحظات المميزة للانتصار والروح الرياضية. تشمل الصور حفل الافتتاح والمسابقات الفردية والجماعية وحفل توزيع الجوائز ولحظات الاحتفال مع الأسر والمعلمين.', 2, 'App\\Models\\Album', 1, '2025-06-30 21:46:38', '2025-06-30 21:46:38'),
	(467, 'title', 'مهرجان الثقافات العالمية 2025', 2, 'App\\Models\\Album', 2, '2025-06-30 21:47:02', '2025-06-30 21:47:02'),
	(468, 'description', 'احتفال نابض بالحياة بالتنوع في مدارس سعود العالمية حيث اجتمع الطلاب والأسر من جنسيات مختلفة لمشاركة تراثهم الثقافي الغني. تضمن المهرجان الأزياء التراثية والعروض الثقافية وأكشاك الطعام الأصيل والمعارض الفنية وورش العمل التفاعلية. قدم الطلاب بلدانهم من خلال الرقص والموسيقى والحكايات والعروض الثقافية، مما خلق تجربة تعليمية عالمية حقيقية تحتفي بمجتمعنا المدرسي متعدد الثقافات.', 2, 'App\\Models\\Album', 2, '2025-06-30 21:47:02', '2025-06-30 21:47:02'),
	(469, 'title', 'Science Fair & Innovation Expo 2025', 1, 'App\\Models\\Event', 1, '2025-06-30 21:49:43', '2025-06-30 21:49:43'),
	(470, 'description', 'Join us for an exciting showcase of student creativity and scientific discovery! Our annual Science Fair & Innovation Expo features innovative projects, experiments, and research presentations by students from grades 6-12. Experience interactive demonstrations, robotics displays, environmental sustainability projects, and cutting-edge technology solutions developed by our talented students. Special guest speakers from leading universities and research institutions will present the latest scientific breakthroughs. This inspiring event celebrates STEM education and encourages future scientists and innovators.', 1, 'App\\Models\\Event', 1, '2025-06-30 21:49:43', '2025-06-30 21:49:43'),
	(471, 'content', '<div style="max-width: 1000px; margin: 0 auto; padding: 40px 20px;">\r\n    <!-- Event 1 -->\r\n    <div style="background: #f8f9fa; padding: 30px; margin-bottom: 30px; border-radius: 10px; border-left: 5px solid #007bff;">\r\n        <h2 style="color: #007bff; margin-bottom: 15px; font-size: 1.8rem;">\r\n            Science Fair &amp; Innovation Expo 2025\r\n        </h2>\r\n        <p style="color: #666; line-height: 1.6; margin-bottom: 20px; font-size: 1.1rem;">\r\n            Join us for an exciting showcase of student creativity and scientific discovery! Our annual Science Fair &amp; Innovation Expo features innovative projects, experiments, and research presentations by students from grades 6-12. Experience interactive demonstrations, robotics displays, environmental sustainability projects, and cutting-edge technology solutions developed by our talented students.\r\n        </p>\r\n        <div style="background: white; padding: 15px; border-radius: 5px; margin-bottom: 15px;">\r\n            <strong style="color: #333;">📅 Date:</strong> March 20, 2025 &nbsp;&nbsp;\r\n            <strong style="color: #333;">🕙 Time:</strong> 10:00 AM - 4:00 PM &nbsp;&nbsp;\r\n            <strong style="color: #333;">📍 Location:</strong> School Gymnasium\r\n        </div>\r\n        <a href="#" style="background: #007bff; color: white; padding: 12px 25px; text-decoration: none; border-radius: 5px; font-weight: bold;">\r\n            Register Now\r\n        </a>\r\n    </div>\r\n\r\n    <!-- Event 2 -->\r\n    <div style="background: #f8f9fa; padding: 30px; margin-bottom: 30px; border-radius: 10px; border-left: 5px solid #28a745;">\r\n        <h2 style="color: #28a745; margin-bottom: 15px; font-size: 1.8rem;">\r\n            International Baccalaureate Information Session\r\n        </h2>\r\n        <p style="color: #666; line-height: 1.6; margin-bottom: 20px; font-size: 1.1rem;">\r\n            Discover the benefits of the International Baccalaureate program at Saud International Schools! This comprehensive information session is designed for parents and students interested in learning about our IB Middle Years Programme (MYP) and Diploma Programme (DP). Meet with IB coordinators, current students, and alumni who will share their experiences.\r\n        </p>\r\n        <div style="background: white; padding: 15px; border-radius: 5px; margin-bottom: 15px;">\r\n            <strong style="color: #333;">📅 Date:</strong> February 15, 2025 &nbsp;&nbsp;\r\n            <strong style="color: #333;">🕕 Time:</strong> 6:00 PM - 8:00 PM &nbsp;&nbsp;\r\n            <strong style="color: #333;">📍 Location:</strong> School Auditorium\r\n        </div>\r\n        <a href="#" style="background: #28a745; color: white; padding: 12px 25px; text-decoration: none; border-radius: 5px; font-weight: bold;">\r\n            Learn More\r\n        </a>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Event', 1, '2025-06-30 21:49:43', '2025-06-30 21:49:43'),
	(472, 'title', 'Science Fair & Innovation Expo 2025', 1, 'App\\Models\\Media', 5, '2025-06-30 21:49:43', '2025-06-30 21:49:43'),
	(473, 'description', 'Join us for an exciting showcase of student creativity and scientific discovery! Our annual Science Fair & Innovation Expo features innovative projects, experiments, and research presentations by students from grades 6-12. Experience interactive demonstrations, robotics displays, environmental sustainability projects, and cutting-edge technology solutions developed by our talented students. Special guest speakers from leading universities and research institutions will present the latest scientific breakthroughs. This inspiring event celebrates STEM education and encourages future scientists and innovators.', 1, 'App\\Models\\Media', 5, '2025-06-30 21:49:43', '2025-06-30 21:49:43'),
	(474, 'title', 'معرض العلوم والابتكار 2025', 2, 'App\\Models\\Event', 1, '2025-06-30 21:50:53', '2025-06-30 21:50:53'),
	(475, 'description', 'انضموا إلينا في عرض مثير للإبداع الطلابي والاكتشاف العلمي! يضم معرض العلوم والابتكار السنوي مشاريع مبتكرة وتجارب وعروض بحثية من قبل طلاب الصفوف 6-12. اختبروا العروض التفاعلية وعروض الروبوتات ومشاريع الاستدامة البيئية والحلول التقنية المتطورة التي طورها طلابنا الموهوبون. متحدثون ضيوف مميزون من جامعات ومؤسسات بحثية رائدة سيقدمون أحدث الاختراقات العلمية. تحتفي هذه الفعالية الملهمة بتعليم العلوم والتكنولوجيا وتشجع علماء ومبتكري المستقبل.', 2, 'App\\Models\\Event', 1, '2025-06-30 21:50:53', '2025-06-30 21:50:53'),
	(476, 'content', '<div style="max-width: 1000px; margin: 0 auto; padding: 40px 20px; direction: rtl;">\r\n    <!-- الفعالية الأولى -->\r\n    <div style="background: #f8f9fa; padding: 30px; margin-bottom: 30px; border-radius: 10px; border-right: 5px solid #007bff;">\r\n        <h2 style="color: #007bff; margin-bottom: 15px; font-size: 1.8rem; line-height: 1.4;">\r\n            معرض العلوم والابتكار 2025\r\n        </h2>\r\n        <p style="color: #666; line-height: 1.8; margin-bottom: 20px; font-size: 1.1rem;">\r\n            انضموا إلينا في عرض مثير للإبداع الطلابي والاكتشاف العلمي! يضم معرض العلوم والابتكار السنوي مشاريع مبتكرة وتجارب وعروض بحثية من قبل طلاب الصفوف 6-12. اختبروا العروض التفاعلية وعروض الروبوتات ومشاريع الاستدامة البيئية والحلول التقنية المتطورة التي طورها طلابنا الموهوبون.\r\n        </p>\r\n        <div style="background: white; padding: 15px; border-radius: 5px; margin-bottom: 15px;">\r\n            <strong style="color: #333;">📅 التاريخ:</strong> 20 مارس 2025 &nbsp;&nbsp;\r\n            <strong style="color: #333;">🕙 الوقت:</strong> 10:00 صباحاً - 4:00 مساءً &nbsp;&nbsp;\r\n            <strong style="color: #333;">📍 المكان:</strong> صالة الألعاب الرياضية\r\n        </div>\r\n        <a href="#" style="background: #007bff; color: white; padding: 12px 25px; text-decoration: none; border-radius: 5px; font-weight: bold;">\r\n            سجل الآن\r\n        </a>\r\n    </div>\r\n\r\n    <!-- الفعالية الثانية -->\r\n    <div style="background: #f8f9fa; padding: 30px; margin-bottom: 30px; border-radius: 10px; border-right: 5px solid #28a745;">\r\n        <h2 style="color: #28a745; margin-bottom: 15px; font-size: 1.8rem; line-height: 1.4;">\r\n            جلسة تعريفية ببرنامج البكالوريا الدولية\r\n        </h2>\r\n        <p style="color: #666; line-height: 1.8; margin-bottom: 20px; font-size: 1.1rem;">\r\n            اكتشفوا فوائد برنامج البكالوريا الدولية في مدارس سعود العالمية! هذه الجلسة التعريفية الشاملة مصممة للأهالي والطلاب المهتمين بتعلم المزيد عن برنامج السنوات المتوسطة (MYP) وبرنامج الدبلوم (DP). التقوا بمنسقي البكالوريا الدولية والطلاب الحاليين والخريجين الذين سيشاركونكم تجاربهم.\r\n        </p>\r\n        <div style="background: white; padding: 15px; border-radius: 5px; margin-bottom: 15px;">\r\n            <strong style="color: #333;">📅 التاريخ:</strong> 15 فبراير 2025 &nbsp;&nbsp;\r\n            <strong style="color: #333;">🕕 الوقت:</strong> 6:00 مساءً - 8:00 مساءً &nbsp;&nbsp;\r\n            <strong style="color: #333;">📍 المكان:</strong> القاعة الكبرى للمدرسة\r\n        </div>\r\n        <a href="#" style="background: #28a745; color: white; padding: 12px 25px; text-decoration: none; border-radius: 5px; font-weight: bold;">\r\n            تعلم أكثر\r\n        </a>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Event', 1, '2025-06-30 21:50:53', '2025-06-30 21:50:53'),
