	(485, 'description', 'Nurturing young learners through a caring, play-based early years programme that fosters curiosity, foundational skills, and holistic development.', 1, 'App\\Models\\Program', 1, '2025-06-30 21:55:04', '2025-07-26 18:09:57'),
	(486, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Laying the Foundation for Lifelong Learning</h2>\r\n\r\n        <p> \r\n            At Saud International School, our Early Learning Stage is more than just a beginning — it is where a child\'s journey into curiosity, confidence, and character truly takes root.\r\n            <br>\r\n            Spanning from KG3 to Reception 2, this foundational phase is intentionally designed to support a child\'s development at every stage — intellectually, socially, emotionally, and physically — within a nurturing and enriched learning environment.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>Curriculum Framework: A Holistic, Values-Driven Approach</h2>\r\n\r\n        <p> \r\n            Our curriculum draws inspiration from international early years best practices, and is aligned with developmental milestones, language acquisition frameworks, and age-appropriate academic readiness. We integrate elements from global standards while remaining sensitive to cultural identity and individual growth.\r\n            <br>\r\n            Through play-based learning, structured activities, and intentional teaching moments, the Early Learning Stage nurtures early literacy, numeracy, communication, independence, emotional resilience, and a love for learning.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/ab50bb9c-fdf1-477d-9d5d-22625c50c6a1.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>✏️ Key Learning Areas</h2>\r\n\r\n        <p> \r\n            Across all levels of the Early Learning Stage, students engage in a rich program that includes:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>English Language Development (Phonics, Vocabulary, Speaking & Listening)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Mathematics (Counting, Shapes, Measurement, Patterns, Logic)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Thematic Science & Discovery</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Fine and Gross Motor Skills (PE, Music, Movement)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Art & Creativity</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Arabic Language</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Islamic Studies (age-appropriate and story-based for Muslim students)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Personal, Social, and Emotional Development (PSED)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Technology & Interactive Learning Tools (age-appropriate screen-free integration)</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🌟 What Sets Our Early Learning Stage Apart?</h2>\r\n\r\n        <div class="row gx-12">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Structured Progression Toward Grade 1</h3>\r\n                <p>Each year level builds seamlessly into the next. By the end of Reception 2, students are confident, independent, and academically ready for the transition into formal primary education.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Dedicated Homeroom Teachers</h3>\r\n                <p>Every classroom is led by experienced early years educators trained in child psychology, language acquisition, and international early learning methodologies.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class="row gx-12 mt-4">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Purpose-Built Learning Spaces</h3>\r\n                <p>Our Early Learning Stage is equipped with vibrant, developmentally appropriate facilities that are safe, engaging, and stimulating for young learners.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Play-Based Learning with Purpose</h3>\r\n                <p>Learning happens through carefully curated play that encourages critical thinking, language use, self-regulation, and collaboration.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class="row gx-12 mt-4">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Home–School Communication</h3>\r\n                <p>Parents receive regular updates, photos, and feedback, and are invited to participate in learning celebrations, storytelling days, and classroom showcases.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ Cultural Awareness & Moral Values</h3>\r\n                <p>Through inclusive storytelling, role-play, and community engagement, we teach respect, empathy, gratitude, and confidence — values we believe are foundational to character building.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 Our Aim in Early Years</h2>\r\n\r\n        <p> \r\n            Our mission in the Early Learning Stage is to ensure that every child:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Develops a strong foundation in literacy, numeracy, and communication</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Feels safe, valued, and excited to come to school every day</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Gains independence, curiosity, and the confidence to ask questions</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Leaves Reception 2 fully prepared — academically, socially, and emotionally — for the transition to Grade 1</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Our Commitment to Early Education</h2>\r\n\r\n        <p> \r\n            At Saud International School, we do not view early education as a stepping stone — we view it as the cornerstone of a student\'s lifelong learning journey.\r\n            <br>\r\n            We invite you to visit our Early Learning Stage and experience the difference for yourself.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Schedule a Visit\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Program', 1, '2025-06-30 21:55:04', '2025-07-26 18:24:56'),
	(487, 'title', 'Early years program', 1, 'App\\Models\\Media', 8, '2025-06-30 21:55:04', '2025-06-30 21:55:04'),
	(488, 'description', 'Our Early Years Program provides a nurturing and stimulating environment where young learners develop foundational skills through play-based learning, exploration, and discovery.', 1, 'App\\Models\\Media', 8, '2025-06-30 21:55:04', '2025-06-30 21:55:04'),
	(489, 'title', 'برنامج السنوات المبكرة', 2, 'App\\Models\\Program', 1, '2025-06-30 21:56:18', '2025-06-30 21:56:18'),
	(490, 'subtitle', 'Prek to KG2', 2, 'App\\Models\\Program', 1, '2025-06-30 21:56:18', '2025-06-30 21:56:18'),
	(491, 'description', 'يوفر برنامج السنوات المبكرة بيئة رعاية ومحفزة حيث يطور المتعلمون الصغار المهارات الأساسية من خلال التعلم القائم على اللعب والاستكشاف والاكتشاف.', 2, 'App\\Models\\Program', 1, '2025-06-30 21:56:18', '2025-06-30 21:56:18'),
	(492, 'content', '<div class="row mt-8">\r\n    <div class="col-12">   \r\n        <h2>وضع الأساس للتعلم مدى الحياة</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، مرحلة التعلم المبكر لدينا ليست مجرد بداية — إنها المكان الذي تبدأ فيه رحلة الطفل في الفضول والثقة والشخصية حقًا.\r\n            <br>\r\n            تمتد من ك ج 3 إلى الاستقبال 2، هذه المرحلة الأساسية مصممة عمدًا لدعم تطور الطفل في كل مرحلة — فكريًا واجتماعيًا وعاطفيًا وجسديًا — ضمن بيئة تعلم داعمة وغنية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>إطار المناهج: نهج شامل قائم على القيم</h2>\r\n\r\n        <p> \r\n            يستلهم منهجنا من أفضل الممارسات الدولية للسنوات المبكرة، وهو محاذي للمعالم التطورية وأطر اكتساب اللغة والاستعداد الأكاديمي المناسب للعمر. ندمج عناصر من المعايير العالمية مع الحفاظ على حساسية الهوية الثقافية والنمو الفردي.\r\n            <br>\r\n            من خلال التعلم القائم على اللعب والأنشطة المنظمة ولحظات التدريس المتعمدة، تغذي مرحلة التعلم المبكر محو الأمية المبكرة والحساب والتواصل والاستقلالية والمرونة العاطفية وحب التعلم.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/ab50bb9c-fdf1-477d-9d5d-22625c50c6a1.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>مجالات التعلم الرئيسية</h2>\r\n\r\n        <p> \r\n            عبر جميع مستويات مرحلة التعلم المبكر، يشارك الطلاب في برنامج غني يتضمن:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>تطوير اللغة الإنجليزية (الصوتيات، المفردات، التحدث والاستماع)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الرياضيات (العد، الأشكال، القياس، الأنماط، المنطق)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>العلوم والاكتشاف الموضوعي</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المهارات الحركية الدقيقة والجسيمة (التربية البدنية، الموسيقى، الحركة)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الفن والإبداع</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>اللغة العربية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الدراسات الإسلامية (مناسبة للعمر وقائمة على القصص للطلاب المسلمين)</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التطور الشخصي والاجتماعي والعاطفي</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التكنولوجيا وأدوات التعلم التفاعلية (دمج خال من الشاشة مناسب للعمر)</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>ما الذي يميز مرحلة التعلم المبكر لدينا؟</h2>\r\n\r\n        <div class="row gx-12">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ التقدم المنظم نحو الصف الأول</h3>\r\n                <p>كل مستوى صفي يبني بسلاسة على التالي. بحلول نهاية الاستقبال 2، يكون الطلاب واثقين ومستقلين ومستعدين أكاديميًا للانتقال إلى التعليم الابتدائي الرسمي.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ معلمو الفصول المخصصون</h3>\r\n                <p>كل فصل دراسي يقوده معلمو السنوات المبكرة ذوو الخبرة المدربون في علم نفس الطفل واكتساب اللغة ومنهجيات التعلم المبكر الدولية.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class="row gx-12 mt-4">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ مساحات التعلم المصممة لغرض محدد</h3>\r\n                <p>مرحلة التعلم المبكر لدينا مجهزة بمرافق حيوية ومناسبة تطوريًا آمنة وجذابة ومحفزة للمتعلمين الصغار.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ التعلم القائم على اللعب مع الغرض</h3>\r\n                <p>يحدث التعلم من خلال اللعب المنسق بعناية الذي يشجع التفكير النقدي واستخدام اللغة والتنظيم الذاتي والتعاون.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class="row gx-12 mt-4">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ التواصل بين المنزل والمدرسة</h3>\r\n                <p>يتلقى الآباء تحديثات منتظمة وصور وتعليقات، ويُدعون للمشاركة في احتفالات التعلم وأيام رواية القصص وعروض الفصول الدراسية.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>✅ الوعي الثقافي والقيم الأخلاقية</h3>\r\n                <p>من خلال رواية القصص الشاملة واللعب التمثيلي والمشاركة المجتمعية، نعلم الاحترام والتعاطف والامتنان والثقة — قيم نعتقد أنها أساسية لبناء الشخصية.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 هدفنا في السنوات المبكرة</h2>\r\n\r\n        <p> \r\n            مهمتنا في مرحلة التعلم المبكر هي ضمان أن كل طفل:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يطور أساسًا قويًا في محو الأمية والحساب والتواصل</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يشعر بالأمان والتقدير والإثارة للذهاب إلى المدرسة كل يوم</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يكتسب الاستقلالية والفضول والثقة لطرح الأسئلة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يترك الاستقبال 2 مستعدًا بالكامل — أكاديميًا واجتماعيًا وعاطفيًا — للانتقال إلى الصف الأول</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>التزامنا بالتعليم المبكر</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، لا ننظر إلى التعليم المبكر كحجر عتبة — ننظر إليه كحجر الزاوية في رحلة التعلم مدى الحياة للطالب.\r\n            <br>\r\n            ندعوك لزيارة مرحلة التعلم المبكر لدينا وتجربة الفرق بنفسك.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                جدولة زيارة\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Program', 1, '2025-06-30 21:56:18', '2025-07-26 18:25:43'),
	(493, 'title', 'Elementary years programme', 1, 'App\\Models\\Program', 2, '2025-06-30 22:03:48', '2025-07-26 18:27:59'),
	(494, 'subtitle', 'Grades 1-5', 1, 'App\\Models\\Program', 2, '2025-06-30 22:03:48', '2025-06-30 22:03:48'),
	(495, 'description', '‎ Nurturing young students’ growth through a balanced, inquiry-based curriculum that fosters critical thinking, creativity, and foundational skills across core subjects.', 1, 'App\\Models\\Program', 2, '2025-06-30 22:03:48', '2025-07-26 19:29:38'),
	(496, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Building Strong Foundations in Knowledge, Character, and Confidence</h2>\r\n\r\n        <p> \r\n            The Elementary Stage (Grades 1 to 5) at Saud International School is where students transition from early learners into structured, independent, and confident young individuals. Our curriculum is carefully mapped and delivered to ensure every child is guided year by year with clarity, consistency, and care — across all subject areas and developmental milestones.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>🧭 Curriculum Framework</h2>\r\n\r\n        <p> \r\n            Our academic structure is based on the American curriculum, drawing alignment from the Common Core State Standards (CCSS) in English and Math, and other internationally benchmarked frameworks in Science and Social Studies. Our curriculum is customized to:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>Meet international academic expectations</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Integrate local requirements set by the Ministry of Education</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Support whole-child development — academically, socially, emotionally, and morally</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            Each grade level builds logically and progressively on the previous one, ensuring vertical alignment in skills, concepts, and outcomes.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>👩‍🏫 The Role of Homeroom Teachers</h2>\r\n\r\n        <p> \r\n            From Grade 1 through Grade 5, every class is led by a dedicated homeroom teacher who plays a central role in the child\'s educational journey.\r\n            <br>\r\n            These teachers are not only responsible for the core academic instruction in English, Math, Science, and Social Studies, but also serve as mentors and advocates — ensuring emotional well-being, personalized support, and daily communication with each student.\r\n        </p>\r\n\r\n        <p class="mb-4">Homeroom teachers are trained to observe, assess, and nurture:</p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Cognitive development through structured lessons</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Social growth through group projects and classroom culture</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Emotional intelligence through open conversations and trust-building</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Values and character through daily routines and modeled behavior</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧠 Academic Focus Areas</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">Subject</th>\r\n                                <th scope="col" width="70%" class="text-primary">Curriculum Highlights</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">English Language Arts</th>\r\n                                <td>Aligned with Common Core – Reading fluency, writing structure, vocabulary, grammar, oral expression</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Mathematics</th>\r\n                                <td>Aligned with Common Core – Number sense, operations, geometry, problem-solving, logical reasoning</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Science</th>\r\n                                <td>Inquiry-based learning, observation, hypothesis, experimentation, thematic units</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Social Studies</th>\r\n                                <td>Local and global awareness, cultural studies, geography, history, citizenship</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Arabic Language</th>\r\n                                <td>In line with Ministry requirements – reading, writing, speaking</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Islamic Studies</th>\r\n                                <td>Moral education, Quranic studies, age-appropriate spiritual growth</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">ICT</th>\r\n                                <td>Basic digital literacy, typing, internet safety, using tools for learning</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Art, Music & PE</th>\r\n                                <td>Fine arts, creativity, physical health, expression, teamwork, self-discipline</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🔁 Progression & Academic Mapping</h2>\r\n\r\n        <p> \r\n            Our curriculum is not delivered in isolation — it is mapped vertically and horizontally:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Vertical alignment ensures every skill and concept introduced in Grade 1 grows in complexity through to Grade 5.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Horizontal integration connects themes and learning across subjects for deeper understanding.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Strengths are reinforced</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Gaps are identified and addressed early</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Personalized strategies are created for student growth</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Each year, homeroom teachers collaborate to pass on academic reports, learning profiles, and developmental insights to the next teacher — ensuring that:\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            This shared communication between grade-level teams ensures consistency, continuity, and care in every child\'s progress.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🌱 Whole-Child Development</h2>\r\n\r\n        <p> \r\n            In Grades 1 to 5, we believe that academic learning must go hand-in-hand with social and emotional development. Through:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Daily routines</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Class discussions</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Value education</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Peer collaboration</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Reflection journals</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Student-led presentations</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            …students develop the confidence to express themselves, the resilience to face challenges, and the empathy to engage meaningfully with others.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📣 Parent Partnership</h2>\r\n\r\n        <p> \r\n            We view parents as essential partners in the learning process. Regular communication through:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Parent–teacher meetings</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Academic reports</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Informal updates</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Homework diaries</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            …ensures that families are consistently involved and informed about their child\'s progress.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 Our Commitment</h2>\r\n\r\n        <p> \r\n            By the time students complete Grade 5, they are not only prepared academically to transition into middle school, but they carry with them the habits, discipline, and self-belief that form the cornerstone of lifelong learning.\r\n            <br>\r\n            Our goal is to raise grounded learners who are curious, capable, and compassionate — equipped to thrive in a changing world.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Schedule a Visit\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Program', 2, '2025-06-30 22:03:48', '2025-07-26 19:33:18'),
	(497, 'title', 'Primary years proramme', 1, 'App\\Models\\Media', 9, '2025-06-30 22:03:48', '2025-06-30 22:03:48'),
	(498, 'description', 'The International Baccalaureate Primary Years Programme (PYP) is designed for children aged 3 to 12.', 1, 'App\\Models\\Media', 9, '2025-06-30 22:03:48', '2025-06-30 22:03:48'),
	(499, 'title', 'برنامج المدرسة الإعدادية', 2, 'App\\Models\\Program', 2, '2025-06-30 22:04:25', '2025-07-26 19:35:25'),
	(500, 'subtitle', 'Grades 1-5', 2, 'App\\Models\\Program', 2, '2025-06-30 22:04:25', '2025-06-30 22:04:25'),
	(501, 'description', '‎رعاية نمو الطلاب الشباب من خلال منهج دراسي متوازن قائم على الاستقصاء يعزز التفكير النقدي والإبداع والمهارات الأساسية في المواد الأساسية.', 2, 'App\\Models\\Program', 2, '2025-06-30 22:04:25', '2025-07-26 19:35:25'),
	(502, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>بناء أسس قوية في المعرفة والشخصية والثقة</h2>\r\n\r\n        <p> \r\n            المرحلة الابتدائية (الصفوف 1 إلى 5) في مدرسة السعود الدولية هي المكان الذي ينتقل فيه الطلاب من المتعلمين المبكرين إلى أفراد شبان منظمين ومستقلين وواثقين. يتم تخطيط مناهجنا وتسليمها بعناية لضمان توجيه كل طفل سنة تلو الأخرى بوضوح واتساق ورعاية — عبر جميع مجالات المواد والمعالم التطورية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>🧭 إطار المناهج</h2>\r\n\r\n        <p> \r\n            هيكلنا الأكاديمي مبني على المنهج الأمريكي، مستمدًا المحاذاة من معايير الدولة الأساسية المشتركة (CCSS) في اللغة الإنجليزية والرياضيات، وأطر أخرى معيارية دوليًا في العلوم والدراسات الاجتماعية. يتم تخصيص مناهجنا لـ:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>تلبية التوقعات الأكاديمية الدولية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>دمج المتطلبات المحلية التي وضعتها وزارة التربية والتعليم</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>دعم التطور الشامل للطفل — أكاديميًا واجتماعيًا وعاطفيًا وأخلاقيًا</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            كل مستوى صفي يبني منطقيًا وتقدميًا على السابق، مما يضمن المحاذاة العمودية في المهارات والمفاهيم والنتائج.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>👩‍🏫 دور معلمي الفصول</h2>\r\n\r\n        <p> \r\n            من الصف الأول حتى الصف الخامس، يقود كل فصل معلم فصل مخصص يلعب دورًا مركزيًا في رحلة الطفل التعليمية.\r\n            <br>\r\n            هؤلاء المعلمون ليسوا مسؤولين فقط عن التعليم الأكاديمي الأساسي في اللغة الإنجليزية والرياضيات والعلوم والدراسات الاجتماعية، ولكنهم أيضًا يخدمون كمرشدين ودعاة — يضمنون الرفاهية العاطفية والدعم الشخصي والتواصل اليومي مع كل طالب.\r\n        </p>\r\n\r\n        <p class="mb-4">يتم تدريب معلمي الفصول لمراقبة وتقييم ورعاية:</p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التطور المعرفي من خلال الدروس المنظمة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>النمو الاجتماعي من خلال المشاريع الجماعية وثقافة الفصل الدراسي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الذكاء العاطفي من خلال المحادثات المفتوحة وبناء الثقة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>القيم والشخصية من خلال الروتين اليومي والسلوك النموذجي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧠 مجالات التركيز الأكاديمية</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">المادة</th>\r\n                                <th scope="col" width="70%" class="text-primary">أبرز المناهج</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">فنون اللغة الإنجليزية</th>\r\n                                <td>محاذاة مع المعايير الأساسية المشتركة – الطلاقة في القراءة، هيكل الكتابة، المفردات، القواعد، التعبير الشفهي</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الرياضيات</th>\r\n                                <td>محاذاة مع المعايير الأساسية المشتركة – الإحساس بالأرقام، العمليات، الهندسة، حل المشكلات، التفكير المنطقي</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">العلوم</th>\r\n                                <td>التعلم القائم على الاستفسار، الملاحظة، الفرضية، التجريب، الوحدات الموضوعية</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الدراسات الاجتماعية</th>\r\n                                <td>الوعي المحلي والعالمي، الدراسات الثقافية، الجغرافيا، التاريخ، المواطنة</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">اللغة العربية</th>\r\n                                <td>وفقًا لمتطلبات الوزارة – القراءة، الكتابة، التحدث</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الدراسات الإسلامية</th>\r\n                                <td>التعليم الأخلاقي، الدراسات القرآنية، النمو الروحي المناسب للعمر</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">تكنولوجيا المعلومات والاتصالات</th>\r\n                                <td>محو الأمية الرقمية الأساسية، الكتابة، أمان الإنترنت، استخدام الأدوات للتعلم</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الفن والموسيقى والتربية البدنية</th>\r\n                                <td>الفنون الجميلة، الإبداع، الصحة البدنية، التعبير، العمل الجماعي، الانضباط الذاتي</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🔁 التقدم والتخطيط الأكاديمي</h2>\r\n\r\n        <p> \r\n            لا يتم تسليم مناهجنا بمعزل — يتم تخطيطها عموديًا وأفقيًا:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المحاذاة العمودية تضمن أن كل مهارة ومفهوم تم تقديمه في الصف الأول ينمو في التعقيد حتى الصف الخامس.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التكامل الأفقي يربط الموضوعات والتعلم عبر المواد لفهم أعمق.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتم تعزيز نقاط القوة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتم تحديد الفجوات ومعالجتها مبكرًا</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتم إنشاء استراتيجيات شخصية لنمو الطالب</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            كل عام، يتعاون معلمو الفصول لتمرير التقارير الأكاديمية والملفات الشخصية للتعلم ورؤى التطور إلى المعلم التالي — مما يضمن أن:\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            هذا التواصل المشترك بين فرق مستوى الصف يضمن الاتساق والاستمرارية والرعاية في تقدم كل طفل.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🌱 التطور الشامل للطفل</h2>\r\n\r\n        <p> \r\n            في الصفوف 1 إلى 5، نعتقد أن التعلم الأكاديمي يجب أن يسير جنبًا إلى جنب مع التطور الاجتماعي والعاطفي. من خلال:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الروتين اليومي</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مناقشات الفصل</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التعليم القيمي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التعاون بين الأقران</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مذكرات التأمل</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>العروض التقديمية بقيادة الطلاب</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            …يطور الطلاب الثقة للتعبير عن أنفسهم، والمرونة لمواجهة التحديات، والتعاطف للتفاعل بشكل هادف مع الآخرين.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📣 شراكة الوالدين</h2>\r\n\r\n        <p> \r\n            ننظر إلى الوالدين كشركاء أساسيين في عملية التعلم. التواصل المنتظم من خلال:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>اجتماعات الوالدين والمعلمين</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التقارير الأكاديمية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التحديثات غير الرسمية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مذكرات الواجبات المنزلية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            …يضمن أن العائلات متورطة ومطلعة باستمرار على تقدم طفلها.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 التزامنا</h2>\r\n\r\n        <p> \r\n            بحلول الوقت الذي يكمل فيه الطلاب الصف الخامس، لا يكونون مستعدين أكاديميًا فقط للانتقال إلى المدرسة المتوسطة، ولكنهم يحملون معهم العادات والانضباط والإيمان بالذات الذي يشكل حجر الزاوية للتعلم مدى الحياة.\r\n            <br>\r\n            هدفنا هو تربية متعلمين متجذرين فضوليين وقادرين ومتعاطفين — مجهزين للازدهار في عالم متغير.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                جدولة زيارة\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Program', 2, '2025-06-30 22:04:25', '2025-07-26 19:35:06'),
	(503, 'title', 'Middle years proramme', 1, 'App\\Models\\Program', 3, '2025-06-30 22:04:51', '2025-06-30 22:04:51'),
	(504, 'subtitle', 'Grades 6-8', 1, 'App\\Models\\Program', 3, '2025-06-30 22:04:51', '2025-07-26 19:37:55'),
	(505, 'description', 'A balanced education for students that fosters critical thinking, creativity, global awareness, and practical connections between learning and the real world.', 1, 'App\\Models\\Program', 3, '2025-06-30 22:04:51', '2025-07-26 19:38:59'),
	(506, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Middle School Curriculum Framework: Grades 6 to 8</h2>\r\n\r\n        <p> \r\n            At Saud International School, the Middle School Stage (Grades 6–8) marks a critical transition in a student\'s educational journey — a time when foundational knowledge is deepened, independence is nurtured, and future pathways begin to take shape.\r\n            <br>\r\n            Our curriculum for Grades 6 to 8 is thoughtfully designed to provide academic rigor, emotional development, and structured subject specialization. We prepare students not just for high school, but for a life of critical thinking, responsibility, and intellectual engagement.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>📘 Curriculum Framework Overview</h2>\r\n\r\n        <p> \r\n            Middle School students follow a curriculum based on the British education system, gradually preparing them for IGCSE studies in Grades 9 and 10. Our program aligns with internationally benchmarked standards while incorporating key educational requirements mandated by the Ministry of Education in Saudi Arabia.\r\n        </p>\r\n\r\n        <p class="mb-4">The framework includes:</p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>Core academic subjects taught by specialist subject teachers</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Skills-based learning in analysis, writing, problem-solving, and communication</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Continuous mapping of curriculum content for smooth progression</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Integration of digital learning, inquiry, and interdisciplinary themes</p>\r\n            </li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧑‍🏫 Subject Specialist Teachers</h2>\r\n\r\n        <p> \r\n            Unlike in Elementary where homeroom teachers deliver most instruction, Middle School students are taught by subject specialists trained in the academic content, assessment, and pedagogy of their particular disciplines. This allows for:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Deeper content knowledge</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Advanced instructional strategies</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Focused academic support in subject-specific areas</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Structured and diverse academic routine</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Students rotate between classes throughout the day, experiencing a more structured and diverse academic routine — similar to the high school model, ensuring a gradual and confident transition into senior school.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 Subjects Offered in Grades 6–8</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">Subject Area</th>\r\n                                <th scope="col" width="70%" class="text-primary">Curriculum Focus</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">English Language</th>\r\n                                <td>Reading comprehension, grammar, writing structure, literary analysis, speaking</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Mathematics</th>\r\n                                <td>Number operations, algebraic thinking, geometry, statistics, real-world application</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Science</th>\r\n                                <td>General science integrating Physics, Chemistry, and Biology fundamentals</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">ICT / Computer Science</th>\r\n                                <td>Digital fluency, basic programming, research skills, software applications</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Social Studies</th>\r\n                                <td>History, geography, culture, global and regional awareness</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Arabic Language</th>\r\n                                <td>Vocabulary building, reading and writing fluency, grammar</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Islamic Studies</th>\r\n                                <td>Quran, Hadith, Islamic values, ethics (for Muslim students)</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Art & Design</th>\r\n                                <td>Creativity, self-expression, visual communication skills</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Physical Education</th>\r\n                                <td>Team sports, personal fitness, coordination, discipline</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🔍 Academic Progression & Curriculum Mapping</h2>\r\n\r\n        <p> \r\n            Our curriculum is vertically aligned, meaning each grade level builds upon the previous year\'s knowledge and skill set. This ensures students:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Develop confidence in tackling more abstract and analytical content</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Strengthen foundational skills in core subjects</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Receive seamless academic progression toward IGCSE-level coursework</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Benefit from synchronized curriculum mapping across subjects</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Our teachers collaborate to ensure that curriculum mapping, learning objectives, and assessment rubrics are synchronized across subjects and grade levels.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧠 Focus on Cognitive and Emotional Growth</h2>\r\n\r\n        <p> \r\n            Middle School is not just about academics. It is a time of personal transformation. Our approach supports:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Critical thinking and independent learning</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Time management and study skills</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Emotional regulation and social development</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Responsible technology use and digital citizenship</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Students are supported through a blend of academic mentoring, classroom activities, assemblies, and values education — equipping them to grow in confidence, purpose, and self-awareness.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📏 Assessments & Checkpoint Exams (Grade 8)</h2>\r\n\r\n        <p> \r\n            Assessment in Middle School is both formative and summative:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Regular quizzes, assignments, projects, and presentations</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Mid-year and end-of-year exams</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Continuous academic tracking and teacher feedback</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Cambridge Lower Secondary Checkpoint Exams in Grade 8</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            In Grade 8, students are prepared for the Cambridge Lower Secondary Checkpoint Exams (or equivalent international benchmark), which assess progress in English, Mathematics, and Science. These exams help guide subject selection in high school and provide parents and students with an international benchmark of readiness for IGCSE studies.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🤝 Communication & Support</h2>\r\n\r\n        <p> \r\n            We maintain strong lines of communication between:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Students and teachers</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Parents and the academic team</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Teachers across grade levels for consistent student support</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Individualized strategies for improvement</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Each student\'s learning profile is carefully tracked year by year to ensure that strengths are enhanced, gaps are addressed, and students are given individualized strategies for improvement. This system ensures that by the time a student enters Grade 9, they are academically prepared and emotionally mature to handle the demands of the IGCSE program.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🏁 Our Vision for Middle School Learners</h2>\r\n\r\n        <p> \r\n            By the end of Grade 8, our students are:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Independent learners</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Confident communicators</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Critical thinkers</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Emotionally balanced young individuals ready for high school</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Our Middle School program is not only about transition — it\'s about transformation. We help students discover who they are, what they are capable of, and how they can impact the world around them.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Schedule a Visit\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Program', 3, '2025-06-30 22:04:51', '2025-07-26 19:49:22'),
	(507, 'title', 'Middle years proramme', 1, 'App\\Models\\Media', 10, '2025-06-30 22:04:51', '2025-06-30 22:04:51'),
	(508, 'description', 'Middle years program', 1, 'App\\Models\\Media', 10, '2025-06-30 22:04:51', '2025-06-30 22:04:51'),
	(509, 'title', 'برنامج المدرسة المتوسطة', 2, 'App\\Models\\Program', 3, '2025-06-30 22:05:14', '2025-06-30 22:05:14'),
	(510, 'subtitle', 'Grades 6-8', 2, 'App\\Models\\Program', 3, '2025-06-30 22:05:14', '2025-07-26 19:38:00'),
	(511, 'description', 'تعليم متوازن للطلاب يعزز التفكير النقدي والإبداع والوعي العالمي والارتباط العملي بين التعلم والعالم الحقيقي.', 2, 'App\\Models\\Program', 3, '2025-06-30 22:05:14', '2025-07-26 19:39:09'),
	(512, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>إطار مناهج المدرسة المتوسطة: الصفوف 6 إلى 8</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، تمثل المرحلة المتوسطة (الصفوف 6-8) انتقالًا حرجًا في رحلة الطالب التعليمية — وقت يتم فيه تعميق المعرفة الأساسية وتنمية الاستقلالية وبدء تشكيل المسارات المستقبلية.\r\n            <br>\r\n            تم تصميم مناهجنا للصفوف 6 إلى 8 بعناية لتوفير الصرامة الأكاديمية والتطور العاطفي والتخصص الموضوعي المنظم. نحن نعد الطلاب ليس فقط للمدرسة الثانوية، ولكن لحياة من التفكير النقدي والمسؤولية والانخراط الفكري.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>📘 نظرة عامة على إطار المناهج</h2>\r\n\r\n        <p> \r\n            يتبع طلاب المدرسة المتوسطة منهجًا مبنيًا على النظام التعليمي البريطاني، مما يعدهم تدريجيًا لدراسات IGCSE في الصفوف 9 و 10. يتوافق برنامجنا مع المعايير الدولية المعيارية مع دمج المتطلبات التعليمية الرئيسية التي تفرضها وزارة التربية والتعليم في المملكة العربية السعودية.\r\n        </p>\r\n\r\n        <p class="mb-4">يشمل الإطار:</p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>المواد الأكاديمية الأساسية التي يدرسها معلمون متخصصون في المواد</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التعلم القائم على المهارات في التحليل والكتابة وحل المشكلات والتواصل</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التخطيط المستمر لمحتوى المناهج للتقدم السلس</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>دمج التعلم الرقمي والاستفسار والمواضيع متعددة التخصصات</p>\r\n            </li>\r\n        </ul>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧑‍🏫 معلمو المواد المتخصصون</h2>\r\n\r\n        <p> \r\n            على عكس المرحلة الابتدائية حيث يقدم معلمو الفصول معظم التعليم، يتم تدريس طلاب المدرسة المتوسطة من قبل متخصصين في المواد مدربين في المحتوى الأكاديمي والتقييم وطرق التدريس في تخصصاتهم المعينة. هذا يسمح بـ:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>معرفة أعمق بالمحتوى</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>استراتيجيات تعليمية متقدمة</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الدعم الأكاديمي المركز في مجالات محددة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الروتين الأكاديمي المنظم والمتنوع</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            يدور الطلاب بين الفصول طوال اليوم، ويختبرون روتينًا أكاديميًا أكثر تنظيماً وتنوعاً — مشابه لنموذج المدرسة الثانوية، مما يضمن انتقالاً تدريجياً وواثقاً إلى المدرسة العليا.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 المواد المقدمة في الصفوف 6-8</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">مجال المادة</th>\r\n                                <th scope="col" width="70%" class="text-primary">تركيز المناهج</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">اللغة الإنجليزية</th>\r\n                                <td>فهم القراءة، القواعد، هيكل الكتابة، التحليل الأدبي، التحدث</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الرياضيات</th>\r\n                                <td>عمليات الأرقام، التفكير الجبري، الهندسة، الإحصاء، التطبيق في العالم الحقيقي</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">العلوم</th>\r\n                                <td>العلوم العامة التي تدمج أساسيات الفيزياء والكيمياء والأحياء</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">تكنولوجيا المعلومات وعلوم الحاسوب</th>\r\n                                <td>الطلاقة الرقمية، البرمجة الأساسية، مهارات البحث، تطبيقات البرمجيات</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الدراسات الاجتماعية</th>\r\n                                <td>التاريخ، الجغرافيا، الثقافة، الوعي العالمي والإقليمي</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">اللغة العربية</th>\r\n                                <td>بناء المفردات، طلاقة القراءة والكتابة، القواعد</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الدراسات الإسلامية</th>\r\n                                <td>القرآن، الحديث، القيم الإسلامية، الأخلاق (للطلاب المسلمين)</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الفن والتصميم</th>\r\n                                <td>الإبداع، التعبير الذاتي، مهارات التواصل البصري</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">التربية البدنية</th>\r\n                                <td>الرياضات الجماعية، اللياقة الشخصية، التنسيق، الانضباط</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🔍 التقدم الأكاديمي وتخطيط المناهج</h2>\r\n\r\n        <p> \r\n            مناهجنا محاذاة عموديًا، مما يعني أن كل مستوى صفي يبني على معرفة ومهارات السنة السابقة. هذا يضمن أن الطلاب:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يطورون الثقة في التعامل مع المحتوى الأكثر تجريدية وتحليلية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يقوون المهارات الأساسية في المواد الأساسية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتلقون تقدمًا أكاديميًا سلسًا نحو مستوى IGCSE</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يستفيدون من تخطيط المناهج المتزامن عبر المواد</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            يتعاون معلمونا لضمان أن تخطيط المناهج وأهداف التعلم ومعايير التقييم متزامنة عبر المواد ومستويات الصفوف.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧠 التركيز على النمو المعرفي والعاطفي</h2>\r\n\r\n        <p> \r\n            المدرسة المتوسطة ليست مجرد أكاديميات. إنها وقت للتحول الشخصي. يدعم نهجنا:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التفكير النقدي والتعلم المستقل</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>إدارة الوقت ومهارات الدراسة</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التنظيم العاطفي والتطور الاجتماعي</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الاستخدام المسؤول للتكنولوجيا والمواطنة الرقمية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            يتم دعم الطلاب من خلال مزيج من الإرشاد الأكاديمي والأنشطة الصفية والتجمعات والتعليم القيمي — مما يجهزهم للنمو في الثقة والهدف والوعي الذاتي.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📏 التقييمات وامتحانات النقاط المرجعية (الصف 8)</h2>\r\n\r\n        <p> \r\n            التقييم في المدرسة المتوسطة تكويني وختامي:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>اختبارات منتظمة وواجبات ومشاريع وعروض تقديمية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>امتحانات منتصف العام ونهاية العام</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التتبع الأكاديمي المستمر وتغذية راجعة المعلم</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>امتحانات كامبريدج للنقاط المرجعية الثانوية الدنيا في الصف 8</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            في الصف 8، يتم إعداد الطلاب لامتحانات كامبريدج للنقاط المرجعية الثانوية الدنيا (أو المعيار الدولي المكافئ)، التي تقيم التقدم في اللغة الإنجليزية والرياضيات والعلوم. تساعد هذه الامتحانات في توجيه اختيار المواد في المدرسة الثانوية وتوفر للوالدين والطلاب معيارًا دوليًا للاستعداد لدراسات IGCSE.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🤝 التواصل والدعم</h2>\r\n\r\n        <p> \r\n            نحافظ على خطوط تواصل قوية بين:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الطلاب والمعلمين</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الوالدين والفريق الأكاديمي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المعلمين عبر مستويات الصفوف لدعم الطلاب المتسق</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>استراتيجيات فردية للتحسين</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            يتم تتبع ملف تعلم كل طالب بعناية سنة تلو الأخرى لضمان تعزيز نقاط القوة ومعالجة الفجوات وإعطاء الطلاب استراتيجيات فردية للتحسين. يضمن هذا النظام أنه بحلول الوقت الذي يدخل فيه الطالب الصف 9، يكون مستعدًا أكاديميًا وناضجًا عاطفيًا للتعامل مع متطلبات برنامج IGCSE.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🏁 رؤيتنا لمتعلمي المدرسة المتوسطة</h2>\r\n\r\n        <p> \r\n            بحلول نهاية الصف 8، طلابنا هم:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>متعلمون مستقلون</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>متواصلون واثقون</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مفكرون نقديون</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>أفراد شبان متوازنون عاطفيًا مستعدون للمدرسة الثانوية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            برنامج المدرسة المتوسطة لدينا ليس فقط حول الانتقال — إنه حول التحول. نساعد الطلاب على اكتشاف من هم وما هم قادرون عليه وكيف يمكنهم التأثير على العالم من حولهم.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                جدولة زيارة\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Program', 3, '2025-06-30 22:05:14', '2025-07-26 19:50:05'),
	(513, 'title', 'Diploma years programme', 1, 'App\\Models\\Program', 4, '2025-06-30 22:06:10', '2025-07-26 19:52:02'),
	(514, 'subtitle', 'Grades 9-12', 1, 'App\\Models\\Program', 4, '2025-06-30 22:06:10', '2025-07-26 19:52:02'),
	(515, 'description', 'A rigorous and balanced education fostering critical thinking, global awareness, and future-ready skills for students.', 1, 'App\\Models\\Program', 4, '2025-06-30 22:06:10', '2025-07-26 19:52:50'),
	(516, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Academic Structure: Grades 9 to 12 (IGCSE & A-Levels)</h2>\r\n\r\n        <p> \r\n            At Saud International School, students in Grades 9 to 12 follow a carefully designed program based on the British curriculum, leading to internationally recognized qualifications through the IGCSE and A-Level pathway. Our academic model is structured to provide both breadth and depth across key subject areas, equipping students with strong foundational knowledge and advanced skills needed for university and beyond.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>📗 Grades 9 & 10 – IGCSE (International General Certificate of Secondary Education)</h2>\r\n\r\n        <p> \r\n            The IGCSE program is spread across two years.\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>In Grade 9, students are introduced to IGCSE subjects and cover approximately 50% of the syllabus.</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>In Grade 10, students complete the remaining content and sit for the external Cambridge or Pearson Edexcel examinations at the end of the academic year.</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            Subject selection is supported through academic counseling to ensure students choose combinations aligned with their strengths and future academic or career goals.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 IGCSE Subjects Offered in Grades 9–10</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">Subject Category</th>\r\n                                <th scope="col" width="70%" class="text-primary">Subjects Offered</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">Core Subjects (Compulsory)</th>\r\n                                <td>English Language, Mathematics, Physics, Chemistry, Biology, Arabic Language, Islamic Studies (for Muslim students), Physical Education (non-examined)</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Elective Subjects (Choose 2-3)</th>\r\n                                <td>Business Studies, Accounting, Economics, ICT (Information & Communication Technology)</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📘 Grades 11 & 12 – A-Level Program (AS & A2)</h2>\r\n\r\n        <p> \r\n            After completing their IGCSEs, students move into the Advanced Level (A-Level) program, which is also a two-year course:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>In Grade 11, students typically enroll in 4 AS-Level subjects.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>At the end of Grade 11, students take their AS-Level external exams.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>In Grade 12, students continue with 3 of the 4 subjects to complete the full A2-Level.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Together with AS forms a full A-Level qualification.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Students receive structured guidance when selecting their A-Level subjects to ensure that their academic profile aligns with their intended university pathways (STEM, business, humanities, medicine, etc.).\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 A-Level Subjects Offered in Grades 11–12</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">Subject Area</th>\r\n                                <th scope="col" width="70%" class="text-primary">Available Subjects</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">Mathematics & Sciences</th>\r\n                                <td>Mathematics, Physics, Chemistry, Biology</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Business & Economics</th>\r\n                                <td>Business, Economics, Accounting</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Languages & ICT</th>\r\n                                <td>English Language, ICT (Information & Communication Technology)</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 Key Features of Our IGCSE & A-Level Program</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Taught by qualified subject specialists with years of experience in the British curriculum.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Strong emphasis on exam preparation, research skills, critical thinking, and academic writing.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Regular internal assessments, mock exams, and personalized academic counseling.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Alignment with university admission expectations both locally and internationally.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📌 University Readiness</h2>\r\n\r\n        <p> \r\n            Our IGCSE and A-Level graduates have successfully gained admission into top-tier universities both within Saudi Arabia and abroad. The academic rigor of our senior school program ensures that students graduate with not only recognized qualifications but also the confidence, maturity, and skill set required for the next stage of their educational journey.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Schedule a Visit\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Program', 4, '2025-06-30 22:06:10', '2025-07-26 20:04:37'),
	(517, 'title', 'Secondary years proramme', 1, 'App\\Models\\Media', 11, '2025-06-30 22:06:10', '2025-06-30 22:06:10'),
	(518, 'description', 'Secondary years proram', 1, 'App\\Models\\Media', 11, '2025-06-30 22:06:10', '2025-06-30 22:06:10'),
	(519, 'title', 'برنامج المدرسة الثانوية', 2, 'App\\Models\\Program', 4, '2025-06-30 22:06:33', '2025-06-30 22:06:33'),
	(520, 'subtitle', 'Grades 9-12', 2, 'App\\Models\\Program', 4, '2025-06-30 22:06:33', '2025-07-26 19:52:06'),
	(521, 'description', 'تعليم صارم ومتوازن يعزز التفكير النقدي والوعي العالمي والمهارات المستقبلية للطلاب.', 2, 'App\\Models\\Program', 4, '2025-06-30 22:06:33', '2025-07-26 19:52:58'),
	(522, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>الهيكل الأكاديمي: الصفوف 9 إلى 12 (IGCSE و A-Levels)</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، يتبع الطلاب في الصفوف 9 إلى 12 برنامجًا مصممًا بعناية مبني على المنهج البريطاني، مما يؤدي إلى مؤهلات معترف بها دوليًا من خلال مسار IGCSE و A-Level. نموذجنا الأكاديمي منظم لتوفير كل من الاتساع والعمق عبر مجالات المواد الرئيسية، مما يجهز الطلاب بالمعرفة الأساسية القوية والمهارات المتقدمة المطلوبة للجامعة وما بعدها.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>📗 الصفوف 9 و 10 – IGCSE (الشهادة العامة الدولية للتعليم الثانوي)</h2>\r\n\r\n        <p> \r\n            برنامج IGCSE موزع على عامين.\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>في الصف 9، يتم تقديم الطلاب لمواد IGCSE ويغطون ما يقرب من 50% من المنهج.</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>في الصف 10، يكمل الطلاب المحتوى المتبقي ويجلسون لامتحانات كامبريدج أو بيرسون إيدكسل الخارجية في نهاية العام الدراسي.</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            يتم دعم اختيار المواد من خلال الإرشاد الأكاديمي لضمان اختيار الطلاب تركيبات متوافقة مع نقاط قوتهم وأهدافهم الأكاديمية أو المهنية المستقبلية.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 المواد المقدمة في IGCSE للصفوف 9-10</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">فئة المادة</th>\r\n                                <th scope="col" width="70%" class="text-primary">المواد المقدمة</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">المواد الأساسية (إجبارية)</th>\r\n                                <td>اللغة الإنجليزية، الرياضيات، الفيزياء، الكيمياء، الأحياء، اللغة العربية، الدراسات الإسلامية (للطلاب المسلمين)، التربية البدنية (غير مفحوصة)</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">المواد الاختيارية (اختر 2-3)</th>\r\n                                <td>دراسات الأعمال، المحاسبة، الاقتصاد، تكنولوجيا المعلومات والاتصالات</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📘 الصفوف 11 و 12 – برنامج A-Level (AS و A2)</h2>\r\n\r\n        <p> \r\n            بعد إكمال IGCSE، ينتقل الطلاب إلى برنامج المستوى المتقدم (A-Level)، وهو أيضًا دورة مدتها عامان:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>في الصف 11، عادة ما يسجل الطلاب في 4 مواد AS-Level.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>في نهاية الصف 11، يخضع الطلاب لامتحانات AS-Level الخارجية.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>في الصف 12، يستمر الطلاب مع 3 من 4 مواد لإكمال A2-Level الكامل.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>معًا مع AS يشكلان مؤهل A-Level كامل.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            يتلقى الطلاب إرشادًا منظمًا عند اختيار مواد A-Level لضمان أن ملفهم الأكاديمي يتوافق مع مسارات الجامعة المقصودة (STEM، الأعمال، العلوم الإنسانية، الطب، إلخ).\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📚 المواد المقدمة في A-Level للصفوف 11-12</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="30%" class="text-primary">مجال المادة</th>\r\n                                <th scope="col" width="70%" class="text-primary">المواد المتاحة</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">الرياضيات والعلوم</th>\r\n                                <td>الرياضيات، الفيزياء، الكيمياء، الأحياء</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">الأعمال والاقتصاد</th>\r\n                                <td>الأعمال، الاقتصاد، المحاسبة</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">اللغات وتكنولوجيا المعلومات</th>\r\n                                <td>اللغة الإنجليزية، تكنولوجيا المعلومات والاتصالات</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 الميزات الرئيسية لبرنامج IGCSE و A-Level لدينا</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يُدرس من قبل متخصصين مؤهلين في المواد مع سنوات من الخبرة في المنهج البريطاني.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>تركيز قوي على التحضير للامتحانات ومهارات البحث والتفكير النقدي والكتابة الأكاديمية.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التقييمات الداخلية المنتظمة والامتحانات التجريبية والإرشاد الأكاديمي الشخصي.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المحاذاة مع توقعات قبول الجامعة محليًا ودوليًا.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📌 الاستعداد للجامعة</h2>\r\n\r\n        <p> \r\n            خريجو IGCSE و A-Level لدينا نجحوا في الحصول على القبول في جامعات من الدرجة الأولى داخل المملكة العربية السعودية وخارجها. الصرامة الأكاديمية لبرنامج المدرسة العليا لدينا تضمن أن الطلاب يتخرجون ليس فقط بمؤهلات معترف بها ولكن أيضًا بالثقة والنضج ومجموعة المهارات المطلوبة للمرحلة التالية من رحلتهم التعليمية.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                جدولة زيارة\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Program', 4, '2025-06-30 22:06:33', '2025-07-26 20:06:18'),
	(523, 'title', 'University & College Guidance', 1, 'App\\Models\\Program', 5, '2025-06-30 22:08:24', '2025-07-26 21:37:10'),
	(524, 'subtitle', 'Grades 11-12', 1, 'App\\Models\\Program', 5, '2025-06-30 22:08:24', '2025-06-30 22:08:24'),
	(525, 'description', 'Comprehensive university and college guidance empowering students with personalized counseling, academic planning, and application support to confidently navigate higher education pathways worldwide.', 1, 'App\\Models\\Program', 5, '2025-06-30 22:08:24', '2025-07-26 21:37:10'),
	(526, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Empowering Students With Purpose, Direction, and Opportunity</h2>\r\n\r\n        <p> \r\n            At Saud International School, we recognize that academic success is just one part of a student\'s journey. Equally important is the clarity and confidence with which they transition into higher education and future careers. That\'s why we have built a comprehensive, student-centered College and Career Guidance Program that supports learners from subject selection in high school through to successful university admissions.\r\n            <br>\r\n            Our goal is simple: to equip every student with the insight, tools, and mentorship needed to make informed decisions about their future.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>🔍 Subject Selection Support (Grades 8–10)</h2>\r\n\r\n        <p> \r\n            The process begins early. In Grade 8, students receive orientation sessions on IGCSE subject pathways, including:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>Detailed explanations of each subject\'s content and expectations</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Insights into how subjects align with potential career interests</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>One-on-one consultations with academic advisors to assess strengths and goals</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            Our teachers and coordinators work collaboratively with students and parents to ensure that by the time they enter Grade 9, every student has a personalized, purposeful subject selection plan.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧭 AS &amp; A-Level Guidance (Grades 11–12)</h2>\r\n\r\n        <p> \r\n            As students move into AS and A-Level studies, the guidance becomes more specialized:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Students are counseled on choosing the right balance of subjects that suit both their abilities and their intended university programs</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Regular check-ins with the academic team help assess progress and adjust plans if necessary</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Students also receive instruction on how to manage rigorous academic loads, prepare for standardized tests, and maintain well-rounded profiles</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧑‍💼 Career Counseling Program</h2>\r\n\r\n        <p> \r\n            Our dedicated Career Counseling Office offers:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Career profiling tools and interest-based assessments</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Individualized guidance on aligning strengths and academic interests with future fields</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Exposure to real-world professions through guest speakers, alumni talks, and themed career weeks</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Resume building, personal statement workshops, and interview preparation sessions</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Our aim is to help students discover their potential and understand the broad spectrum of academic and career opportunities available to them—locally, regionally, and globally.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🌐 University Engagement &amp; Application Support</h2>\r\n\r\n        <p> \r\n            Every year, top universities from around the world visit Saud International School to meet our students. These university outreach events include:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Campus presentations and open forums for Q&amp;A</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Information booths for students and parents</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Application workshops and scholarship briefings</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>One-on-one sessions with admissions representatives</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Universities from countries such as the UK, USA, Canada, Malaysia, UAE, and Europe regularly participate—offering our students first-hand insight into international admissions expectations.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📝 University Application Process</h2>\r\n\r\n        <p> \r\n            Our college guidance team works side-by-side with students to support every step of the application journey:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Choosing the right universities based on program, location, and eligibility</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Drafting and refining personal statements, motivation letters, and application essays</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Completing UCAS, Common App, and other national application systems</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Meeting deadlines for standardized testing, transcripts, recommendations, and financial aid</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            Whether a student aims for medical school, engineering, business, the arts, or liberal studies, we ensure they have a roadmap and support system tailored to their ambitions.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🤝 Partnership with Parents</h2>\r\n\r\n        <p> \r\n            Throughout the process, parents are kept closely involved:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Information sessions on university trends and subject requirements</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Parent–student–counselor meetings for strategic planning</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Regular updates through newsletters and progress reports</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            We understand that planning a student\'s future is a collaborative process. Our job is to make it clearer, smarter, and more empowering.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 Our Promise</h2>\r\n\r\n        <p> \r\n            We don\'t simply prepare students to graduate — we prepare them to excel at the next level. With a proven system of academic advising, career coaching, and university preparation, our students leave Saud International School with:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>A strong academic foundation</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>A clear sense of direction</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>The confidence to navigate higher education and beyond</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            At Saud International School, your child\'s journey doesn\'t end at Grade 12 — it truly begins there.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Schedule a Visit\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Program', 5, '2025-06-30 22:08:24', '2025-07-26 21:37:10'),
	(527, 'title', 'IB Diploma program', 1, 'App\\Models\\Media', 12, '2025-06-30 22:08:24', '2025-06-30 22:08:24'),
	(528, 'description', 'IB Diploma program', 1, 'App\\Models\\Media', 12, '2025-06-30 22:08:24', '2025-06-30 22:08:24'),
	(529, 'title', 'امتحان تحضير البكالوريا', 2, 'App\\Models\\Program', 5, '2025-06-30 22:08:43', '2025-06-30 22:08:43'),
	(530, 'subtitle', 'Grades 11-12', 2, 'App\\Models\\Program', 5, '2025-06-30 22:08:43', '2025-06-30 22:08:43'),
	(531, 'description', 'الإرشاد الجامعي الشامل للطلاب من خلال الاستشارات الشخصية والتخطيط الأكاديمي ودعم التقديم للتنقل بثقة في مسارات التعليم العالي في جميع أنحاء العالم.', 2, 'App\\Models\\Program', 5, '2025-06-30 22:08:43', '2025-07-26 21:37:15'),
	(532, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>تمكين الطلاب بالهدف والاتجاه والفرصة</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، ندرك أن النجاح الأكاديمي هو مجرد جزء واحد من رحلة الطالب. بنفس القدر من الأهمية هي الوضوح والثقة التي ينتقلون بها إلى التعليم العالي والمهن المستقبلية. لهذا السبب بنينا برنامجًا شاملاً ومركزيًا للتوجيه الجامعي والمهني يدعم المتعلمين من اختيار المواد في المدرسة الثانوية حتى القبول الجامعي الناجح.\r\n            <br>\r\n            هدفنا بسيط: تجهيز كل طالب بالرؤية والأدوات والإرشاد اللازم لاتخاذ قرارات مدروسة حول مستقبلهم.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>🔍 دعم اختيار المواد (الصفوف 8-10)</h2>\r\n\r\n        <p> \r\n            تبدأ العملية مبكرًا. في الصف 8، يتلقى الطلاب جلسات توجيه حول مسارات مواد IGCSE، بما في ذلك:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>شروحات مفصلة لمحتوى كل مادة وتوقعاتها</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>رؤى حول كيفية محاذاة المواد مع الاهتمامات المهنية المحتملة</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>استشارات فردية مع المستشارين الأكاديميين لتقييم نقاط القوة والأهداف</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p class="mt-4">\r\n            يعمل معلمونا ومنسقونا بشكل تعاوني مع الطلاب والوالدين لضمان أنه بحلول الوقت الذي يدخلون فيه الصف 9، يكون لدى كل طالب خطة شخصية وهادفة لاختيار المواد.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/13622dc7-e72d-454f-b56c-431fb4ecee10.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧭 التوجيه في AS و A-Level (الصفوف 11-12)</h2>\r\n\r\n        <p> \r\n            مع انتقال الطلاب إلى دراسات AS و A-Level، يصبح التوجيه أكثر تخصصًا:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتم إرشاد الطلاب حول اختيار التوازن الصحيح للمواد التي تناسب قدراتهم وبرامج الجامعة المقصودة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الفحوصات المنتظمة مع الفريق الأكاديمي تساعد في تقييم التقدم وتعديل الخطط إذا لزم الأمر</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>يتلقى الطلاب أيضًا تعليمات حول كيفية إدارة الأحمال الأكاديمية الصارمة والتحضير للاختبارات المعيارية والحفاظ على الملفات الشخصية المتوازنة</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🧑‍💼 برنامج الإرشاد المهني</h2>\r\n\r\n        <p> \r\n            يقدم مكتب الإرشاد المهني المخصص لدينا:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>أدوات التوصيف المهني والتقييمات القائمة على الاهتمام</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>إرشاد فردي حول محاذاة نقاط القوة والاهتمامات الأكاديمية مع المجالات المستقبلية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التعرض للمهن في العالم الحقيقي من خلال المتحدثين الضيوف ومحادثات الخريجين وأسابيع المهن المواضيعية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>بناء السيرة الذاتية وورش عمل البيان الشخصي وجلسات التحضير للمقابلات</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            هدفنا هو مساعدة الطلاب على اكتشاف إمكاناتهم وفهم الطيف الواسع من الفرص الأكاديمية والمهنية المتاحة لهم — محليًا وإقليميًا وعالميًا.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🌐 مشاركة الجامعة ودعم التطبيق</h2>\r\n\r\n        <p> \r\n            كل عام، تزور أفضل الجامعات من جميع أنحاء العالم مدرسة السعود الدولية للقاء طلابنا. تشمل أحداث التواصل الجامعي هذه:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>العروض التقديمية في الحرم الجامعي والمنتديات المفتوحة للأسئلة والأجوبة</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>أكشاك المعلومات للطلاب والوالدين</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>ورش عمل التطبيق والإحاطات حول المنح الدراسية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>جلسات فردية مع ممثلي القبول</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            تشارك الجامعات من دول مثل المملكة المتحدة والولايات المتحدة وكندا وماليزيا والإمارات وأوروبا بانتظام — مما يقدم لطلابنا رؤية مباشرة لتوقعات القبول الدولية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>📝 عملية التطبيق الجامعي</h2>\r\n\r\n        <p> \r\n            يعمل فريق التوجيه الجامعي لدينا جنبًا إلى جنب مع الطلاب لدعم كل خطوة من رحلة التطبيق:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>اختيار الجامعات المناسبة بناءً على البرنامج والموقع والأهلية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>صياغة وتحسين البيانات الشخصية وخطابات التحفيز ومقالات التطبيق</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>إكمال UCAS و Common App وأنظمة التطبيق الوطنية الأخرى</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الوفاء بالمواعيد النهائية للاختبارات المعيارية والنصوص والتوصيات والمساعدات المالية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            سواء كان الطالب يهدف إلى كلية الطب أو الهندسة أو الأعمال أو الفنون أو الدراسات الليبرالية، نضمن أن لديهم خريطة طريق ونظام دعم مصمم لطموحاتهم.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🤝 الشراكة مع الوالدين</h2>\r\n\r\n        <p> \r\n            طوال العملية، يتم إبقاء الوالدين مشاركين عن كثب:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>جلسات معلومات حول اتجاهات الجامعة ومتطلبات المواد</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>اجتماعات الوالدين والطالب والمستشار للتخطيط الاستراتيجي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>التحديثات المنتظمة من خلال النشرات الإخبارية وتقارير التقدم</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            نفهم أن تخطيط مستقبل الطالب هو عملية تعاونية. مهمتنا هي جعلها أوضح وأذكى وأكثر تمكينًا.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 وعدنا</h2>\r\n\r\n        <p> \r\n            نحن لا نعد الطلاب للتخرج ببساطة — نحن نعدهم للتميز في المستوى التالي. مع نظام مثبت من الإرشاد الأكاديمي والتدريب المهني والتحضير الجامعي، يغادر طلابنا مدرسة السعود الدولية بـ:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>أساس أكاديمي قوي</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>إحساس واضح بالاتجاه</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الثقة للتنقل في التعليم العالي وما بعده</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p class="mt-4">\r\n            في مدرسة السعود الدولية، رحلة طفلك لا تنتهي في الصف 12 — إنها تبدأ حقًا هناك.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="/visits" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                جدولة زيارة\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Program', 5, '2025-06-30 22:08:43', '2025-07-26 21:36:53'),
