	(662, 'title', 'Eschool', 1, 'App\\Models\\MenuItem', 21, '2025-07-25 18:36:38', '2025-07-27 09:17:57'),
	(663, 'title', 'Welcome', 1, 'App\\Models\\Page', 14, '2025-07-26 09:33:19', '2025-07-26 09:33:19'),
	(664, 'description', 'Excellence in Education, Grounded in Values, Inspired by Vision.', 1, 'App\\Models\\Page', 14, '2025-07-26 09:33:19', '2025-07-26 09:33:19'),
	(665, 'content', '<div class="row align-items-center">\r\n    <div class="d-flex col-12 col-lg-3 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/90886e98-6f15-4eee-a44d-bb51df19d3b2.png" alt="logo.png">\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-9 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>Welcome to saud international schools</h2>\r\n        <blockquote>\r\n            <p>\r\n                Excellence in Education, Grounded in Values, Inspired by Vision.\r\n            </p>\r\n        </blockquote>\r\n\r\n        <p> \r\n            We are a school built on integrity, academic strength, and generational trust — where students grow into confident, capable individuals prepared to lead, contribute, and thrive with purpose.\r\n        </p>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 14, '2025-07-26 09:33:19', '2025-07-26 10:43:13'),
	(666, 'title', 'Welcome', 1, 'App\\Models\\Media', 25, '2025-07-26 09:33:19', '2025-07-26 09:33:19'),
	(667, 'description', 'Excellence in Education, Grounded in Values, Inspired by Vision.', 1, 'App\\Models\\Media', 25, '2025-07-26 09:33:19', '2025-07-26 09:33:19'),
	(668, 'title', 'مرحبا بكم', 2, 'App\\Models\\Page', 14, '2025-07-26 09:44:25', '2025-07-26 09:44:25'),
	(669, 'description', 'التميز في التعليم، مبني على القيم، مستوحى من الرؤية.', 2, 'App\\Models\\Page', 14, '2025-07-26 09:44:25', '2025-07-26 09:44:25'),
	(670, 'content', '<div class="row align-items-center">\r\n    <div class="d-flex col-12 col-lg-3 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/90886e98-6f15-4eee-a44d-bb51df19d3b2.png" alt="logo.png">\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-9 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>مرحبا بكم في مدارس سعود العالمية</h2>\r\n        <blockquote>\r\n            <p>\r\n                التميز في التعليم، مبني على القيم، مستوحى من الرؤية.\r\n            </p>\r\n        </blockquote>\r\n\r\n        <p> \r\n            نحن مدرسة مبنية على النزاهة والقوة الأكاديمية والثقة بين الأجيال - حيث ينمو الطلاب إلى أفراد واثقين وقادرين ومستعدين للقيادة والمساهمة والازدهار بهدف.\r\n        </p>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 14, '2025-07-26 09:44:25', '2025-07-26 10:43:22'),
	(671, 'title', 'Mission And Philosophy', 1, 'App\\Models\\Page', 15, '2025-07-26 10:46:24', '2025-07-26 10:46:24'),
	(672, 'description', 'A dynamic and inclusive educational community empowering thoughtful leaders and lifelong learners to thrive with knowledge, character, and purpose.', 1, 'App\\Models\\Page', 15, '2025-07-26 10:46:24', '2025-07-26 10:46:24'),
	(673, 'content', '<div class="row align-items-center">\r\n    <div class="col-12 col-lg-8 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>Vision Statement</h2>\r\n\r\n        <p> \r\n            To be a beacon of transformative education that cultivates generations of thoughtful leaders and lifelong learners—empowered with knowledge, character, and purpose to thrive in a rapidly changing world.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="d-flex col-12 col-lg-4 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/0bc6ce32-5862-41d2-8a8c-a0927986c28d.png" alt="image_2025-07-26_124451448.png"> \r\n    </div>\r\n</div>\r\n\r\n<div class="row align-items-center mt-8">\r\n    <div class="d-flex col-12 col-lg-4 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/ca0317c9-199c-4bf7-8384-83f6a4c5614f.jpg" alt="pexels-emily-ranquist-493228-1205651.jpg">\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-8 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>Mission Statement</h2>\r\n\r\n\r\n        <p> \r\n            To provide a dynamic, inclusive, and forward-thinking learning environment that nurtures each student’s intellectual, emotional, social, and ethical development. Through high expectations and deep respect for tradition, we empower students to lead with integrity, think critically, and contribute purposefully to society—today and for generations to come. \r\n        </p>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 15, '2025-07-26 10:46:24', '2025-07-26 10:47:46'),
	(674, 'title', 'Mission And Philosophy', 1, 'App\\Models\\Media', 26, '2025-07-26 10:46:24', '2025-07-26 10:46:24'),
	(675, 'description', 'A dynamic and inclusive educational community empowering thoughtful leaders and lifelong learners to thrive with knowledge, character, and purpose.', 1, 'App\\Models\\Media', 26, '2025-07-26 10:46:24', '2025-07-26 10:46:24'),
	(676, 'title', 'رسالتنا وفلسفتنا', 2, 'App\\Models\\Page', 15, '2025-07-26 10:49:46', '2025-07-26 10:49:46'),
	(677, 'description', 'مجتمع تعليمي ديناميكي وشامل يعمل على تمكين القادة المفكرين والمتعلمين مدى الحياة من النجاح بالمعرفة والشخصية والغرض.', 2, 'App\\Models\\Page', 15, '2025-07-26 10:49:46', '2025-07-26 10:49:46'),
	(678, 'content', '<div class="row align-items-center">\r\n    <div class="col-12 col-lg-8 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>رؤيتنا</h2>\r\n\r\n        <p> \r\n            أن نكون منارة للتعليم التحويلي الذي ينشئ أجيالاً من القادة المفكرين والمتعلمين مدى الحياة - المتمكنين من المعرفة والشخصية والغرض للنجاح في عالم سريع التغير.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="d-flex col-12 col-lg-4 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/0bc6ce32-5862-41d2-8a8c-a0927986c28d.png" alt="image_2025-07-26_124451448.png"> \r\n    </div>\r\n</div>\r\n\r\n<div class="row align-items-center mt-8">\r\n    <div class="d-flex col-12 col-lg-4 justify-content-center align-items-center px-4">\r\n        <img src="/storage/uploads/ca0317c9-199c-4bf7-8384-83f6a4c5614f.jpg" alt="pexels-emily-ranquist-493228-1205651.jpg">\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-8 text-center text-lg-start mt-8 mt-lg-0 px-0 px-lg-4">   \r\n        <h2>رسالتنا</h2>\r\n\r\n\r\n        <p> \r\n            توفير بيئة تعليمية ديناميكية وشاملة وتطلعية، تُنمّي النمو الفكري والعاطفي والاجتماعي والأخلاقي لكل طالب. من خلال توقعات عالية واحترام عميق للتقاليد، نُمكّن الطلاب من القيادة بنزاهة، والتفكير النقدي، والمساهمة الهادفة في المجتمع - اليوم وللأجيال القادمة.\r\n        </p>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 15, '2025-07-26 10:49:46', '2025-07-26 10:49:46'),
	(679, 'title', 'History of SIS', 1, 'App\\Models\\Page', 16, '2025-07-26 10:57:56', '2025-07-26 10:57:56'),
	(680, 'description', 'A long-standing legacy of intercultural excellence and transformative education.', 1, 'App\\Models\\Page', 16, '2025-07-26 10:57:56', '2025-07-26 15:06:54'),
	(681, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Our Legacy: A Story of Purpose, People, and Progress</h2>\r\n\r\n        <p> \r\n            Founded in 1981, Saud International School began with a clear purpose — to offer a world-class education rooted in strong values, academic excellence, and an unwavering commitment to developing the next generation of capable, confident, and morally grounded individuals.\r\n            <br>\r\n            Over the decades, the school has grown from a modest academic institution into one of Riyadh’s most respected and enduring educational establishments. We proudly serve students from Preschool to Grade 12, offering both the American and British curricula, and educating boys and girls in a dynamic and inclusive environment.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Our Journey: 1981 to 2025 and Beyond</h2>\r\n\r\n        <p> \r\n            Since our establishment, we have remained steadfast in our belief that education is more than textbooks and exams — it is about preparing individuals to understand themselves, serve others, and contribute meaningfully to the world around them.\r\n            <br>\r\n            Our graduates today are doctors, engineers, entrepreneurs, educators, and leaders — occupying respected positions in countries around the globe. Many of them are now proud parents themselves, returning to enroll their own children in the very classrooms that shaped their early years — a testament to our lasting impact and generational trust.\r\n            <br>\r\n            We have continuously evolved over the years — adapting to advancements in technology, curriculum development, and teaching methodologies — all while staying true to our original ethos: values-based, holistic education.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Our Philosophy of Education</h2>\r\n\r\n        <p> \r\n            At Saud International School, we believe education must develop the whole child — intellectually, emotionally, socially, spiritually, and morally. Our goal is not simply to produce high achievers, but to nurture individuals of strong character who can lead with wisdom, empathy, and integrity.\r\n            <br>\r\n            We view every student as a unique individual with distinct potential. Our classrooms are places where curiosity is encouraged, critical thinking is developed, and creativity is celebrated.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Our Objectives & Aims</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To ensure academic excellence through a rigorous and relevant curriculum</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To instill moral and ethical values as guiding principles in students\' lives</p>\r\n                    </li>\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To foster critical thinking, leadership, and a sense of civic responsibility</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">  \r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To create a safe, nurturing, and inclusive school community</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To develop confidence, communication, and emotional resilience in every learner</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>To prepare students to thrive in higher education, the workforce, and society</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Beyond Academics: A Complete Education</h2>\r\n\r\n        <p> \r\n            We believe school should be a launchpad for life. That’s why our educational program extends far beyond the classroom — through co-curricular activities, leadership opportunities, student clubs, competitions, sports, community service, and more.\r\n            <br>\r\n            Every child who walks through our gates is guided not only to achieve, but to understand, reflect, and grow — as a student, as a citizen, and as a human being.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Ethos of Leadership and Service</h2>\r\n\r\n        <p> \r\n            Our leadership is grounded in service — not only to our students, but to the educational landscape of Saudi Arabia. We believe in leading with humility, vision, and responsibility. The school’s management team is composed of experienced professionals who are deeply invested in the growth of each individual and the collective success of our learning community.\r\n            <br>\r\n            We do not just manage a school; we cultivate a culture — one that inspires learning, rewards effort, and uplifts everyone it touches.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>A Legacy Aligned with the Kingdom’s Vision</h2>\r\n\r\n        <p> \r\n            As Saudi Arabia moves forward with Vision 2030, we are proud to play a role in shaping the generation that will carry that vision forward. Our commitment to innovation, character education, and global readiness aligns with the national goal of building a knowledge-based society, and we are honored to contribute to the Kingdom’s future through the work we do every day.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Looking Ahead</h2>\r\n\r\n        <p> \r\n            We carry with us more than 40 years of excellence, but our eyes are always on the future. With each passing year, we renew our promise: to stay rooted in purpose, to move forward with integrity, and to ensure that every student who walks through our doors is prepared — not just for school, but for life.\r\n            <br>\r\n            Welcome to Saud International School.\r\n            <br>\r\n            Where education becomes legacy.\r\n        </p>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 16, '2025-07-26 10:57:56', '2025-07-26 16:55:39'),
	(682, 'title', 'History of SIS', 1, 'App\\Models\\Media', 27, '2025-07-26 10:57:56', '2025-07-26 10:57:56'),
	(683, 'description', 'A long-standing legacy of intercultural excellence and transformative education since 1995.', 1, 'App\\Models\\Media', 27, '2025-07-26 10:57:56', '2025-07-26 10:57:56'),
	(684, 'title', 'تاريخنا', 2, 'App\\Models\\Page', 16, '2025-07-26 15:07:06', '2025-07-26 15:07:06'),
	(685, 'description', 'إرث طويل الأمد من التميز بين الثقافات والتعليم.', 2, 'App\\Models\\Page', 16, '2025-07-26 15:07:06', '2025-07-26 15:07:06'),
	(686, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>إرثنا: قصة الهدف والأشخاص والتقدم</h2>\r\n\r\n        <p> \r\n            تأسست مدرسة السعود الدولية في عام 1981 بهدف واضح — تقديم تعليم عالمي المستوى متجذر في القيم القوية والتميز الأكاديمي والالتزام الثابت بتطوير الجيل القادم من الأفراد القادرين والواثقين والمتأصلين أخلاقياً.\r\n            <br>\r\n            على مر العقود، نمت المدرسة من مؤسسة أكاديمية متواضعة إلى واحدة من أكثر المؤسسات التعليمية احتراماً وديمومة في الرياض. نحن نفخر بخدمة الطلاب من مرحلة ما قبل المدرسة إلى الصف الثاني عشر، ونقدم المناهج الأمريكية والبريطانية، ونعلم الأولاد والبنات في بيئة ديناميكية وشاملة.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>رحلتنا: من 1981 إلى 2025 وما بعده</h2>\r\n\r\n        <p> \r\n            منذ تأسيسنا، ظللنا ثابتين في إيماننا بأن التعليم أكثر من الكتب المدرسية والامتحانات — إنه يتعلق بإعداد الأفراد لفهم أنفسهم وخدمة الآخرين والمساهمة بمعنى في العالم من حولهم.\r\n            <br>\r\n            خريجونا اليوم هم أطباء ومهندسون ورجال أعمال ومعلمون وقادة — يشغلون مناصب محترمة في دول حول العالم. كثير منهم أصبحوا آباء فخورين الآن، ويعودون لتسجيل أطفالهم في نفس الفصول الدراسية التي شكلت سنواتهم الأولى — شهادة على تأثيرنا الدائم والثقة بين الأجيال.\r\n            <br>\r\n            لقد تطورنا باستمرار على مر السنين — متكيفين مع التطورات في التكنولوجيا وتطوير المناهج وطرق التدريس — مع البقاء مخلصين لأصولنا الأصلية: التعليم الشامل القائم على القيم.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>فلسفتنا في التعليم</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، نؤمن بأن التعليم يجب أن يطور الطفل كاملاً — فكرياً وعاطفياً واجتماعياً وروحياً وأخلاقياً. هدفنا ليس مجرد إنتاج المتفوقين، بل تنمية أفراد ذوي شخصية قوية يمكنهم القيادة بالحكمة والتعاطف والنزاهة.\r\n            <br>\r\n            ننظر إلى كل طالب كفرد فريد بإمكانيات مميزة. فصولنا الدراسية هي أماكن حيث يتم تشجيع الفضول وتطوير التفكير النقدي والاحتفال بالإبداع.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>أهدافنا وغاياتنا</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li><span><i class="uil uil-check"></i></span><span>ضمان التميز الأكاديمي من خلال منهج صارم وملائم</span></li>\r\n                    <li class="mt-3"><span><i class="uil uil-check"></i></span><span>غرس القيم الأخلاقية والمبادئ كقواعد توجيهية في حياة الطلاب</span></li>\r\n                    <li class="mt-3"><span><i class="uil uil-check"></i></span><span>تعزيز التفكير النقدي والقيادة والشعور بالمسؤولية المدنية</span></li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li><span><i class="uil uil-check"></i></span><span>إنشاء مجتمع مدرسي آمن ومحفز وشامل</span></li>\r\n                    <li class="mt-3"><span><i class="uil uil-check"></i></span><span>تطوير الثقة والتواصل والمرونة العاطفية في كل متعلم</span></li>\r\n                    <li class="mt-3"><span><i class="uil uil-check"></i></span><span>إعداد الطلاب للنجاح في التعليم العالي وسوق العمل والمجتمع</span></li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>ما وراء الأكاديمية: تعليم شامل</h2>\r\n\r\n        <p> \r\n            نؤمن بأن المدرسة يجب أن تكون منصة انطلاق للحياة. لهذا يمتد برنامجنا التعليمي إلى ما هو أبعد من الفصل الدراسي — من خلال الأنشطة المشتركة وفرص القيادة والنوادي الطلابية والمسابقات والرياضة وخدمة المجتمع والمزيد.\r\n            <br>\r\n            كل طفل يمر عبر بواباتنا يتم توجيهه ليس فقط للتحقيق، بل للفهم والتأمل والنمو — كطالب وكمواطن وكإنسان.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>فلسفة القيادة والخدمة</h2>\r\n\r\n        <p> \r\n            قيادتنا متجذرة في الخدمة — ليس فقط لطلابنا، بل للمشهد التعليمي في المملكة العربية السعودية. نؤمن بالقيادة بالتواضع والرؤية والمسؤولية. فريق إدارة المدرسة مكون من متخصصين ذوي خبرة مستثمرين بعمق في نمو كل فرد والنجاح الجماعي لمجتمعنا التعليمي.\r\n            <br>\r\n            نحن لا ندير مدرسة فحسب؛ بل نزرع ثقافة — واحدة تلهم التعلم وتكافئ الجهد وترفع كل من تلمسه.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>إرث متوافق مع رؤية المملكة</h2>\r\n\r\n        <p> \r\n            مع تقدم المملكة العربية السعودية نحو رؤية 2030، نفخر بلعب دور في تشكيل الجيل الذي سيحمل هذه الرؤية إلى الأمام. التزامنا بالابتكار والتعليم القائم على الشخصية والجاهزية العالمية يتوافق مع الهدف الوطني لبناء مجتمع قائم على المعرفة، ونشعر بالفخر للمساهمة في مستقبل المملكة من خلال العمل الذي نقوم به كل يوم.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>نظرة إلى المستقبل</h2>\r\n\r\n        <p> \r\n            نحمل معنا أكثر من 40 عاماً من التميز، لكن أعيننا دائماً على المستقبل. مع كل عام يمر، نجد وعدنا: البقاء متجذرين في الهدف، والتقدم إلى الأمام بالنزاهة، وضمان أن كل طالب يمر عبر أبوابنا يكون مستعداً — ليس فقط للمدرسة، بل للحياة.\r\n            <br>\r\n            مرحباً بكم في مدرسة السعود الدولية.\r\n            <br>\r\n            حيث يصبح التعليم إرثاً.\r\n        </p>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 16, '2025-07-26 15:07:06', '2025-07-26 15:09:25'),
	(687, 'title', 'Faculty', 1, 'App\\Models\\Page', 17, '2025-07-26 15:12:41', '2025-07-26 15:12:41'),
	(688, 'description', 'Dedicated educators and support professionals committed to fostering a nurturing and innovative learning environment.', 1, 'App\\Models\\Page', 17, '2025-07-26 15:12:41', '2025-07-26 15:12:41'),
	(689, 'content', '<div class="row align-items-center">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>Our Faculty &amp; Staff</h2>\r\n\r\n        <p> \r\n            At Saud International School, our faculty is not just a team — it is a carefully curated community of educators who are deeply committed to the intellectual and personal growth of every student.\r\n            <br>\r\n            With over four decades of legacy behind us, we understand that the quality of a school lies not just in its curriculum, but in the people who bring that curriculum to life.\r\n            <br>\r\n            Our teaching faculty is composed of highly qualified professionals from a range of cultural and academic backgrounds. We proudly represent a diverse blend of nationalities, including educators from the United States, the United Kingdom, South Africa, Jordan, Egypt, Lebanon, India, Pakistan, and the Philippines, among others. This international mix brings richness and perspective to our classrooms, promoting global understanding, academic rigor, and inclusive learning environments that reflect the values of our school and the diversity of our student body.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/1995d69e-1d04-46a0-af55-96107adf50eb.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Structured for Excellence</h2>\r\n\r\n        <p> \r\n            We employ a tiered instructional model to ensure that our teaching structure matches the developmental and academic needs of our students:\r\n        </p>\r\n\r\n        <div class="row gx-12">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>Preschool to Grade 5:</h3>\r\n                <p>These early and foundational years are led by dedicated homeroom teachers who provide integrated instruction across core subjects. These teachers work closely with students throughout the day, fostering a nurturing, consistent, and well-rounded learning experience that supports academic progress, emotional growth, and positive behavior.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>Grades 6 to 12:</h3>\r\n                <p>From Grade 6 onward, students are taught by subject-specialist teachers who bring a high level of expertise in their fields. Whether it’s Physics, Math, Literature, ICT, Business, or Islamic Studies, each subject is taught by an educator trained specifically in that discipline. This model prepares students for the depth and pace of secondary education and beyond.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Commitment to Professional Development</h2>\r\n\r\n        <p> \r\n            We believe that learning never stops — not just for our students, but for our teachers as well. At Saud International School, professional development is continuous, structured, and mission-aligned. We invest in:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Ongoing training workshops in instructional best practices, classroom technology, and curriculum integration.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>International certifications and development programs for leadership and subject mastery.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Regular internal peer observations and feedback loops to encourage reflective teaching and growth.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Strategic academic reviews to ensure alignment with both the American and British curricula and with the evolving needs of our students.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p> \r\n            Our teachers are not only expected to teach — they are expected to inspire, model integrity, and be co-creators of the school’s vision in action.\r\n        </p>\r\n\r\n        <p> \r\n            Many of our staff members are also deeply involved in the co-curricular life of the school — leading clubs, coaching sports teams, mentoring student leadership councils, and guiding school-wide events and cultural programs. Their presence extends beyond the lesson plan, creating meaningful relationships with students that support confidence, resilience, and well-being.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>Leadership You Can Trust</h2>\r\n\r\n        <p> \r\n            Our faculty works under the guidance of an experienced academic leadership team that ensures every teacher, lesson, and classroom contributes to the high standards Saud International School is known for.\r\n            <br>\r\n            We are proud that many of our educators have been with us for years — and even decades — witnessing the growth of their students from young learners into young leaders. It is this continuity and dedication that make our school not just a place of instruction, but a place of legacy.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>A Culture of High Standards and Deep Care</h2>\r\n\r\n        <p> \r\n            We know that great teaching comes from a combination of knowledge, empathy, discipline, and vision. That’s why we hold our faculty to the highest professional and ethical standards — ensuring that every child in our care receives a rich, thoughtful, and engaging education every single day.\r\n            <br>\r\n            When you choose Saud International School, you are choosing more than a curriculum —\r\n            You are choosing a team of educators who understand the responsibility of shaping minds and hearts, and who have done so with excellence, generation after generation.\r\n        </p>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 17, '2025-07-26 15:12:41', '2025-07-26 15:34:03'),
	(690, 'title', 'Faculty', 1, 'App\\Models\\Media', 28, '2025-07-26 15:12:41', '2025-07-26 15:12:41'),
