	(693, 'description', 'المعلمون المتفانون والمتخصصون في الدعم ملتزمون بتعزيز بيئة تعليمية داعمة ومبتكرة.', 2, 'App\\Models\\Page', 17, '2025-07-26 15:35:59', '2025-07-26 15:35:59'),
	(694, 'content', '<div class="row align-items-center">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>هيئة التدريس والموظفين</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، هيئة التدريس لدينا ليست مجرد فريق — بل هي مجتمع منظم بعناية من المعلمين الملتزمين بعمق بالنمو الفكري والشخصي لكل طالب.\r\n            <br>\r\n            مع أكثر من أربعة عقود من الإرث خلفنا، نفهم أن جودة المدرسة لا تكمن فقط في مناهجها، بل في الأشخاص الذين يجعلون هذه المناهج حية.\r\n            <br>\r\n            هيئة التدريس لدينا مكونة من متخصصين مؤهلين تأهيلاً عالياً من خلفيات ثقافية وأكاديمية متنوعة. نفخر بتمثيل مزيج متنوع من الجنسيات، بما في ذلك معلمين من الولايات المتحدة والمملكة المتحدة وجنوب أفريقيا والأردن ومصر ولبنان والهند وباكستان والفلبين، وغيرهم. هذا المزيج الدولي يجلب الثراء والمنظور إلى فصولنا الدراسية، ويعزز الفهم العالمي والصرامة الأكاديمية وبيئات التعلم الشاملة التي تعكس قيم مدرستنا وتنوع طلابنا.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6"> \r\n        <img src="/storage/uploads/1995d69e-1d04-46a0-af55-96107adf50eb.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>منظم للتميز</h2>\r\n\r\n        <p> \r\n            نستخدم نموذج تعليمي متدرج لضمان أن هيكل التدريس لدينا يتطابق مع الاحتياجات التطويرية والأكاديمية لطلابنا:\r\n        </p>\r\n\r\n        <div class="row gx-12">\r\n            <div class="col-12 col-lg-6">\r\n                <h3>مرحلة ما قبل المدرسة إلى الصف الخامس:</h3>\r\n                <p>هؤلاء السنوات المبكرة والأساسية يقودها معلمون مخصصون للفصول الدراسية يوفرون تعليماً متكاملاً عبر المواد الأساسية. يعمل هؤلاء المعلمون عن كثب مع الطلاب طوال اليوم، ويعززون تجربة تعليمية محفزة ومتسقة ومتوازنة تدعم التقدم الأكاديمي والنمو العاطفي والسلوك الإيجابي.</p>\r\n            </div>\r\n\r\n            <div class="col-12 col-lg-6">\r\n                <h3>الصف السادس إلى الصف الثاني عشر:</h3>\r\n                <p>من الصف السادس فصاعداً، يتم تدريس الطلاب من قبل معلمين متخصصين في المواد يجلبون مستوى عالياً من الخبرة في مجالاتهم. سواء كانت الفيزياء أو الرياضيات أو الأدب أو تقنية المعلومات أو الأعمال أو الدراسات الإسلامية، كل مادة يتم تدريسها من قبل معلم مدرب خصيصاً في ذلك التخصص. هذا النموذج يعد الطلاب لعمق وسرعة التعليم الثانوي وما بعده.</p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>الالتزام بالتطوير المهني</h2>\r\n\r\n        <p> \r\n            نؤمن بأن التعلم لا يتوقف أبداً — ليس فقط لطلابنا، بل لمعلمينا أيضاً. في مدرسة السعود الدولية، التطوير المهني مستمر ومنظم ومتوافق مع الرسالة. نستثمر في:\r\n        </p>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>ورش عمل تدريبية مستمرة في أفضل ممارسات التدريس وتكنولوجيا الفصول الدراسية وتكامل المناهج.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الشهادات الدولية وبرامج التطوير للقيادة وإتقان المواد الدراسية.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>ملاحظات الأقران الداخلية المنتظمة وحلقات التغذية الراجعة لتشجيع التدريس التأملي والنمو.</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مراجعات أكاديمية استراتيجية لضمان التوافق مع المناهج الأمريكية والبريطانية ومع الاحتياجات المتطورة لطلابنا.</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n\r\n        <p> \r\n            معلمونا ليسوا مطلوبين للتدريس فحسب — بل مطلوب منهم الإلهام ونمذجة النزاهة وأن يكونوا مشاركين في خلق رؤية المدرسة في العمل.\r\n        </p>\r\n\r\n        <p> \r\n            كثير من موظفينا متورطون بعمق في الحياة المشتركة للمدرسة — قيادة النوادي وتدريب الفرق الرياضية وإرشاد مجالس قيادة الطلاب وتوجيه الأحداث المدرسية والبرامج الثقافية. وجودهم يمتد إلى ما هو أبعد من خطة الدرس، مما يخلق علاقات هادفة مع الطلاب تدعم الثقة والمرونة والرفاهية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>قيادة يمكنك الوثوق بها</h2>\r\n\r\n        <p> \r\n            تعمل هيئة التدريس لدينا تحت إشراف فريق قيادة أكاديمية ذو خبرة يضمن أن كل معلم ودرس وفصل دراسي يساهم في المعايير العالية التي تشتهر بها مدرسة السعود الدولية.\r\n            <br>\r\n            نفخر بأن كثيراً من معلمينا كانوا معنا لسنوات — وحتى لعقود — شاهدين نمو طلابهم من متعلمين صغار إلى قادة شباب. هذه الاستمرارية والتفاني هي التي تجعل مدرستنا ليست مجرد مكان للتعليم، بل مكان للإرث.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>ثقافة المعايير العالية والرعاية العميقة</h2>\r\n\r\n        <p> \r\n            نعلم أن التدريس العظيم يأتي من مزيج من المعرفة والتعاطف والانضباط والرؤية. لهذا نحمل هيئة التدريس لدينا أعلى المعايير المهنية والأخلاقية — ضمان أن كل طفل في رعايتنا يتلقى تعليماً غنياً ومدروساً وجذاباً كل يوم.\r\n            <br>\r\n            عندما تختار مدرسة السعود الدولية، أنت تختار أكثر من منهج —\r\n            أنت تختار فريقاً من المعلمين الذين يفهمون مسؤولية تشكيل العقول والقلوب، والذين فعلوا ذلك بالتميز، جيلاً بعد جيل.\r\n        </p>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 17, '2025-07-26 15:35:59', '2025-07-26 15:35:59'),
