	(715, 'title', 'School Policies', 1, 'App\\Models\\MenuItem', 32, '2025-07-26 15:50:56', '2025-07-26 15:50:56'),
	(716, 'title', 'سياسات المدرسة', 2, 'App\\Models\\MenuItem', 32, '2025-07-26 15:51:04', '2025-07-26 15:51:04'),
	(717, 'title', 'Academics overview', 1, 'App\\Models\\Page', 18, '2025-07-26 16:29:36', '2025-07-26 16:29:36'),
	(718, 'description', 'Inspiring academic excellence through a rigorous, inclusive curriculum that nurtures critical thinking, creativity, and lifelong learning.', 1, 'App\\Models\\Page', 18, '2025-07-26 16:29:36', '2025-07-26 16:29:36'),
	(719, 'content', '<div class="row">\r\n    <div class="col-12">\r\n        <h2>Academics Overview</h2>\r\n\r\n        <p>\r\n            At Saud International School, our academic program is carefully designed to provide a comprehensive, balanced, and forward-thinking education that meets both international expectations and local educational standards. We offer a dual-curriculum pathway, structured to serve students from Preschool through Grade 12, while aligning with educational benchmarks and regulatory guidelines recognized within the Kingdom of Saudi Arabia.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>Preschool to Grade 5: A Strong Early Foundation</h2>\r\n\r\n        <p> \r\n            From Preschool through Grade 5, students follow a curriculum inspired by American educational principles, incorporating key aspects of international best practices. The early years emphasize:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>Literacy and numeracy fundamentals</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Inquiry-based learning</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Social-emotional development</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Cross-curricular integration</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Age-appropriate digital and hands-on learning experiences</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p>\r\n            Our academic framework in the elementary levels reflects the general philosophy and expectations outlined in international standards while integrating values-based learning and moral development.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6 ps-4"> \r\n        <img src="/storage/uploads/0487a574-ace0-4648-869f-706b18c71db7.png">\r\n    </div>\r\n</div>\r\n\r\n\r\n<div class="row mt-8">\r\n    <div class="col-12 col-lg-6 ps-4"> \r\n        <img src="/storage/uploads/c47b17d4-e78c-4617-abf5-1a806cf2090b.png">    \r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>Grade 6 to Grade 12: Rigorous and Globally Oriented</h2>\r\n\r\n        <p> \r\n            From Grade 6 onward, our students transition into a curriculum modeled after the British educational framework, supported by a progressive subject-based structure. This phase prepares students for academic specialization and success in external examinations.\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>Core subjects including English, Mathematics, Sciences, and Social Studies</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Specialist instruction in ICT, Business, Economics, and the Humanities</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Language acquisition, including Arabic and Islamic Studies, in line with national expectations</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>Skill-building in critical thinking, problem-solving, research, and academic writing</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p>\r\n            Assessment is varied, meaningful, and intended to support both academic growth and readiness for higher education pathways.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>Curriculum Design and Mapping</h2>\r\n\r\n        <p>\r\n            We follow a well-structured curriculum mapping process that takes into consideration:\r\n        </p>\r\n\r\n        <div class="row">\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>International academic benchmarks</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Core educational standards</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n\r\n            <div class="col-lg-6">  \r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Local ministry requirements</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>The developmental and academic needs of our student body</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n        <p>\r\n            This ensures that learning objectives are vertically and horizontally aligned across all grade levels, providing students with continuity, depth, and coherence in their academic journey.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>Educational Philosophy</h2>\r\n\r\n        <p>\r\n            Our academic model is driven by a philosophy that values balance, relevance, and adaptability. We believe that students must be equipped not only with strong academic foundations, but also with the skills and mindset needed to succeed in an increasingly complex world.\r\n        </p>\r\n\r\n        <p>\r\n            Our educators work collaboratively to ensure that every learner receives a well-rounded education that integrates:\r\n        </p>\r\n\r\n        <div class="row">\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                <li>\r\n                    <i class="uil uil-check"></i>\r\n                    <p>Academics</p>\r\n                </li>\r\n                <li class="mt-3">\r\n                    <i class="uil uil-check"></i>\r\n                    <p>Values</p>\r\n                </li>\r\n                <li class="mt-3">\r\n                    <i class="uil uil-check"></i>\r\n                    <p>Technology</p>\r\n                </li>\r\n            </div>\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Creativity</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Real-world readiness</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>Our Commitment</h2>\r\n    </div>\r\n\r\n    <p>\r\n        We are committed to providing an academic environment where learning is purposeful, progress is measurable, and student growth is holistic. Through regular curriculum reviews, professional development for our staff, and a strong academic support system, we continue to evolve while staying true to our educational mission and the trust placed in us by generations of families.\r\n    </p>\r\n</div>', 1, 'App\\Models\\Page', 18, '2025-07-26 16:29:36', '2025-07-26 16:53:40'),
	(720, 'title', 'Academics overview', 1, 'App\\Models\\Media', 30, '2025-07-26 16:29:36', '2025-07-26 16:29:36'),
	(721, 'description', 'Inspiring academic excellence through a rigorous, inclusive curriculum that nurtures critical thinking, creativity, and lifelong learning.', 1, 'App\\Models\\Media', 30, '2025-07-26 16:29:36', '2025-07-26 16:29:36'),
	(722, 'title', 'الشؤون الأكاديمية', 2, 'App\\Models\\Page', 18, '2025-07-26 18:07:12', '2025-07-26 18:07:12'),
	(723, 'description', 'إلهام التميز الأكاديمي من خلال منهج دراسي صارم وشامل يغذي التفكير النقدي والإبداع والتعلم مدى الحياة.', 2, 'App\\Models\\Page', 18, '2025-07-26 18:07:12', '2025-07-26 18:07:12'),
	(724, 'content', '<div class="row mt-8">\r\n    <div class="col-12">\r\n        <h2>نظرة عامة على الأكاديمية:</h2>\r\n        \r\n        <p>\r\n            في مدرسة السعود الدولية، تم تصميم برنامجنا الأكاديمي بعناية لتوفير تعليم شامل ومتوازن ومتطلع للمستقبل يلبي التوقعات الدولية والمعايير التعليمية المحلية. نقدم مسار مناهج مزدوج، منظم لخدمة الطلاب من مرحلة ما قبل المدرسة حتى الصف الثاني عشر، مع التزام بالمعايير التعليمية والمبادئ التوجيهية التنظيمية المعترف بها في المملكة العربية السعودية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>من مرحلة ما قبل المدرسة إلى الصف الخامس: أساس قوي مبكر</h2>\r\n\r\n        <p> \r\n            من مرحلة ما قبل المدرسة حتى الصف الخامس، يتبع الطلاب منهجًا مستوحى من المبادئ التعليمية الأمريكية، مع دمج الجوانب الرئيسية لأفضل الممارسات الدولية. تركز السنوات المبكرة على:\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>أساسيات القراءة والكتابة والحساب</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التعلم القائم على الاستفسار</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التنمية الاجتماعية والعاطفية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التكامل بين المواد الدراسية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>تجارب التعلم الرقمية والعملية المناسبة للعمر</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p>\r\n            يعكس إطارنا الأكاديمي في المستويات الابتدائية الفلسفة والتوقعات العامة المحددة في المعايير الدولية مع دمج التعلم القائم على القيم والتطور الأخلاقي.\r\n        </p>\r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6 ps-4"> \r\n        <img src="/storage/uploads/0487a574-ace0-4648-869f-706b18c71db7.png">\r\n    </div>\r\n</div>\r\n\r\n<div class="row mt-8">\r\n    <div class="col-12 col-lg-6 ps-4"> \r\n        <img src="/storage/uploads/c47b17d4-e78c-4617-abf5-1a806cf2090b.png">    \r\n    </div>\r\n\r\n    <div class="col-12 col-lg-6">   \r\n        <h2>من الصف السادس إلى الصف الثاني عشر: صارم ومتوجه عالميًا</h2>\r\n\r\n        <p> \r\n            من الصف السادس فصاعدًا، ينتقل طلابنا إلى منهج مستوحى من الإطار التعليمي البريطاني، مدعوم ببنية موضوعية تقدمية. هذه المرحلة تعد الطلاب للتخصص الأكاديمي والنجاح في الامتحانات الخارجية.\r\n        </p>\r\n\r\n        <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n            <li>\r\n                <i class="uil uil-check"></i>\r\n                <p>المواد الأساسية بما في ذلك اللغة الإنجليزية والرياضيات والعلوم والدراسات الاجتماعية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>التعليم المتخصص في تكنولوجيا المعلومات والاتصالات والأعمال والاقتصاد والعلوم الإنسانية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>اكتساب اللغة، بما في ذلك اللغة العربية والدراسات الإسلامية، وفقًا للتوقعات الوطنية</p>\r\n            </li>\r\n            <li class="mt-3">\r\n                <i class="uil uil-check"></i>\r\n                <p>بناء المهارات في التفكير النقدي وحل المشكلات والبحث والكتابة الأكاديمية</p>\r\n            </li>\r\n        </ul>\r\n\r\n        <p>\r\n            التقييم متنوع وهادف ومصمم لدعم النمو الأكاديمي والاستعداد لمسارات التعليم العالي.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>تصميم وتخطيط المناهج</h2>\r\n\r\n        <p>\r\n            نتبع عملية تخطيط مناهج منظمة تأخذ في الاعتبار:\r\n        </p>\r\n\r\n        <div class="row">\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المعايير الأكاديمية الدولية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>المعايير التعليمية الأساسية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n\r\n            <div class="col-lg-6">  \r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>متطلبات الوزارة المحلية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الاحتياجات التطورية والأكاديمية لطلابنا</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n        <p>\r\n            هذا يضمن أن أهداف التعلم محاذاة عموديًا وأفقيًا عبر جميع المستويات الصفية، مما يوفر للطلاب الاستمرارية والعمق والتماسك في رحلتهم الأكاديمية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>الفلسفة التعليمية</h2>\r\n\r\n        <p>\r\n            يحرك نموذجنا الأكاديمي فلسفة تقدر التوازن والملاءمة والقدرة على التكيف. نعتقد أن الطلاب يجب أن يكونوا مجهزين ليس فقط بأساسيات أكاديمية قوية، ولكن أيضًا بالمهارات والعقلية اللازمة للنجاح في عالم معقد بشكل متزايد.\r\n        </p>\r\n\r\n        <p>\r\n            يعمل معلمونا بشكل تعاوني لضمان أن كل متعلم يتلقى تعليمًا متوازنًا يدمج:\r\n        </p>\r\n\r\n        <div class="row">\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                <li>\r\n                    <i class="uil uil-check"></i>\r\n                    <p>الأكاديميات</p>\r\n                </li>\r\n                <li class="mt-3">\r\n                    <i class="uil uil-check"></i>\r\n                    <p>القيم</p>\r\n                </li>\r\n                <li class="mt-3">\r\n                    <i class="uil uil-check"></i>\r\n                    <p>التكنولوجيا</p>\r\n                </li>\r\n            </div>\r\n            <div class="col-lg-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الإبداع</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الاستعداد للعالم الحقيقي</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">\r\n        <h2>التزامنا</h2>\r\n    </div>\r\n\r\n    <p>\r\n        نحن ملتزمون بتوفير بيئة أكاديمية يكون فيها التعلم هادفًا والتقدم قابل للقياس ونمو الطالب شموليًا. من خلال المراجعات المنتظمة للمناهج والتطوير المهني لموظفينا ونظام دعم أكاديمي قوي، نستمر في التطور مع البقاء مخلصين لرسالتنا التعليمية والثقة التي وضعتها فينا أجيال من العائلات.\r\n    </p>\r\n</div>', 2, 'App\\Models\\Page', 18, '2025-07-26 18:07:12', '2025-07-26 18:07:12'),
