	(750, 'title', 'الإرشاد الجامعي والكليات', 2, 'App\\Models\\MenuItem', 45, '2025-07-27 07:03:30', '2025-07-27 07:03:30'),
	(751, 'title', 'Apply Now', 1, 'App\\Models\\Page', 19, '2025-07-27 07:09:10', '2025-07-27 07:09:10'),
	(752, 'description', 'Start your journey with us—apply now for a transformative education that empowers thoughtful leaders and lifelong learners.', 1, 'App\\Models\\Page', 19, '2025-07-27 07:09:10', '2025-07-27 07:09:10'),
	(753, 'content', '<div class="row">   \r\n    <div class="col-12">   \r\n        <h2>Apply now for Admission</h2>\r\n\r\n        <p> \r\n            At Saudi International School, we believe that every child deserves the opportunity to thrive in an environment that nurtures their potential and prepares them for a bright future. Our comprehensive educational approach combines academic excellence with character development, ensuring students are well-equipped for the challenges of tomorrow.\r\n            <br>\r\n            Join our community of learners and discover the difference that quality education makes in shaping young minds.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="https://eregistration.sis.edu.sa/en-GB/Saud" target="_blank" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                Apply now\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 19, '2025-07-27 07:09:10', '2025-07-27 07:09:10'),
	(754, 'title', 'طلب التسجيل', 2, 'App\\Models\\Page', 19, '2025-07-27 07:09:29', '2025-07-27 07:09:29'),
	(755, 'description', 'ابدأ رحلتك معنا - تقدم الآن للحصول على تعليم تحويلي يعمل على تمكين القادة المفكرين والمتعلمين مدى الحياة.', 2, 'App\\Models\\Page', 19, '2025-07-27 07:09:29', '2025-07-27 07:09:39'),
	(756, 'content', '<div class="row">   \r\n    <div class="col-12">   \r\n        <h2>قم بتقديم طلب التسجيل</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، نؤمن بأن كل طفل يستحق الفرصة للازدهار في بيئة ترعى إمكانياته وتعدّه لمستقبل مشرق. نهجنا التعليمي الشامل يجمع بين التميز الأكاديمي وتطوير الشخصية، مما يضمن أن الطلاب مجهزون جيداً لتحديات الغد.\r\n            <br>\r\n            انضم إلى مجتمعنا التعليمي واكتشف الفرق الذي يحدثه التعليم الجيد في تشكيل العقول الشابة.\r\n        </p>\r\n\r\n        <div class="text-start mt-6">\r\n            <a href="https://eregistration.sis.edu.sa/en-GB/Saud" target="_blank" class="btn btn-primary rounded text-center">\r\n                <i class="uil uil-angle-right-b me-2"></i>\r\n                تقديم طلب التسجيل\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 19, '2025-07-27 07:09:29', '2025-07-27 07:09:29'),
	(757, 'title', 'School Fees', 1, 'App\\Models\\Page', 20, '2025-07-27 07:18:22', '2025-07-27 07:18:22'),
	(758, 'description', 'Clear and transparent school fees covering tuition, registration, and essential services, designed to support quality education and student development.', 1, 'App\\Models\\Page', 20, '2025-07-27 07:18:22', '2025-07-27 07:18:22'),
	(759, 'content', '<div class="row">   \r\n    <div class="col-12">   \r\n        <h2>School Fees Structure</h2>\r\n\r\n        <p> \r\n            At Saudi International School, we believe in providing exceptional educational value that reflects the quality of our comprehensive curriculum, experienced faculty, and world-class facilities. Our fee structure is designed to be transparent and competitive, ensuring that families receive outstanding educational services that prepare students for future success.\r\n            <br>\r\n            Our fees cover all essential academic programs, learning resources, technology integration, and extracurricular activities that contribute to a well-rounded educational experience.\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            Please fill out our <a href="/inquiries" class="text-primary">General Inquiry form</a> if you would like more information from a member of our admissions team.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>💰 Annual Tuition Fees</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="40%" class="text-primary">Educational Level</th>\r\n                                <th scope="col" width="30%" class="text-primary">Grade Range</th>\r\n                                <th scope="col" width="30%" class="text-primary">Annual Fee (SAR)</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">Early School Programme</th>\r\n                                <td>Pre-Foundation to Reception 2</td>\r\n                                <td class="text-primary fw-bold">40,000 SAR</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Elementary School Programme</th>\r\n                                <td>Grades 1-5</td>\r\n                                <td class="text-primary fw-bold">48,000 SAR</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Middle School Programme</th>\r\n                                <td>Grades 6-9</td>\r\n                                <td class="text-primary fw-bold">53,000 SAR</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">Diploma Years Programme</th>\r\n                                <td>Grades 10-12</td>\r\n                                <td class="text-primary fw-bold">58,000 SAR</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                \r\n                <div class="alert alert-info mt-4 mb-0">\r\n                    <i class="uil uil-info-circle me-2"></i>\r\n                    <strong>Note:</strong> All fees are quoted in Saudi Riyal (SAR) and do not include VAT.\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 20, '2025-07-27 07:18:22', '2025-07-27 07:21:15'),
	(760, 'title', 'الرسوم الدراسية', 2, 'App\\Models\\Page', 20, '2025-07-27 07:20:45', '2025-07-27 07:20:59'),
	(761, 'description', 'رسوم مدرسية واضحة وشفافة تغطي الرسوم الدراسية والتسجيل والخدمات الأساسية، وهي مصممة لدعم التعليم الجيد وتنمية الطلاب.', 2, 'App\\Models\\Page', 20, '2025-07-27 07:20:45', '2025-07-27 07:20:59'),
	(762, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>هيكل الرسوم الدراسية</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، نؤمن بتقديم قيمة تعليمية استثنائية تعكس جودة مناهجنا الشاملة وهيئة التدريس ذوي الخبرة والمرافق العالمية. تم تصميم هيكل رسومنا ليكون شفافًا ومنافسًا، مما يضمن أن العائلات تتلقى خدمات تعليمية متميزة تعد الطلاب للنجاح المستقبلي.\r\n            <br>\r\n            تغطي رسومنا جميع البرامج الأكاديمية الأساسية والموارد التعليمية وتكامل التكنولوجيا والأنشطة اللامنهجية التي تساهم في تجربة تعليمية شاملة.\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            يرجى ملء <a href="/inquiries" class="text-primary">نموذج الاستفسار العام</a> إذا كنت ترغب في الحصول على مزيد من المعلومات من أحد أعضاء فريق القبول لدينا.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>💰 الرسوم الدراسية السنوية</h2>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="table-responsive">\r\n                    <table class="table">\r\n                        <thead>\r\n                            <tr>\r\n                                <th scope="col" width="40%" class="text-primary">المستوى التعليمي</th>\r\n                                <th scope="col" width="30%" class="text-primary">نطاق الصفوف</th>\r\n                                <th scope="col" width="30%" class="text-primary">الرسوم السنوية (ريال)</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <tr>\r\n                                <th scope="row">برنامج المدرسة المبكرة</th>\r\n                                <td>ما قبل التأسيس إلى الاستقبال 2</td>\r\n                                <td class="text-primary fw-bold">40,000 ريال</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">برنامج المدرسة الابتدائية</th>\r\n                                <td>الصفوف 1-5</td>\r\n                                <td class="text-primary fw-bold">48,000 ريال</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">برنامج المدرسة المتوسطة</th>\r\n                                <td>الصفوف 6-9</td>\r\n                                <td class="text-primary fw-bold">53,000 ريال</td>\r\n                            </tr>\r\n                            <tr>\r\n                                <th scope="row">برنامج سنوات الدبلوم</th>\r\n                                <td>الصفوف 10-12</td>\r\n                                <td class="text-primary fw-bold">58,000 ريال</td>\r\n                            </tr>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                \r\n                <div class="alert alert-info mt-4 mb-0">\r\n                    <i class="uil uil-info-circle me-2"></i>\r\n                    <strong>ملاحظة:</strong> جميع الرسوم مقومة بالريال السعودي ولا تشمل ضريبة القيمة المضافة.\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 20, '2025-07-27 07:20:45', '2025-07-27 07:21:52'),
	(763, 'title', 'Admissions', 1, 'App\\Models\\MenuItem', 46, '2025-07-27 07:25:53', '2025-07-27 07:25:53'),
	(764, 'title', 'Apply Now', 1, 'App\\Models\\MenuItem', 47, '2025-07-27 07:26:12', '2025-07-27 07:26:12'),
	(765, 'title', 'School Fees', 1, 'App\\Models\\MenuItem', 48, '2025-07-27 07:26:29', '2025-07-27 07:26:29'),
	(766, 'title', 'Academic Calendar', 1, 'App\\Models\\MenuItem', 49, '2025-07-27 07:27:02', '2025-07-27 07:27:02'),
	(767, 'title', 'Request a Call Back', 1, 'App\\Models\\Page', 21, '2025-07-27 07:36:07', '2025-07-27 07:36:07'),
	(768, 'description', 'Quick and easy request for a personalized call back to discuss admissions, programs, and school inquiries.', 1, 'App\\Models\\Page', 21, '2025-07-27 07:36:07', '2025-07-27 07:36:07'),
	(769, 'content', '<div class="row">   \r\n    <div class="col-12">   \r\n        <h2>Request a Callback</h2>\r\n\r\n        <p> \r\n            We understand that choosing the right school for your child is one of the most important decisions you\'ll make. Our dedicated admissions team is here to help you every step of the way.\r\n            <br>\r\n            Whether you have questions about our curriculum, facilities, admission process, or would like to schedule a personalized consultation, we\'re ready to assist you with all the information you need to make an informed decision.\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            Our team will get back to you as soon as possible to discuss your specific needs and answer any questions you may have about Saudi International School.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>📞 How It Works</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-phone-volume"></i>\r\n                    </div>\r\n                    <h4>1. Request Callback</h4>\r\n                    <p class="mb-0">Fill out our inquiry form with your contact details and preferred callback time.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-clock"></i>\r\n                    </div>\r\n                    <h4>2. We\'ll Contact You</h4>\r\n                    <p class="mb-0">Our admissions team will call you as soon as possible at your preferred time.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-comments"></i>\r\n                    </div>\r\n                    <h4>3. Get Your Answers</h4>\r\n                    <p class="mb-0">Discuss your questions and learn about our programs, facilities, and admission process.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>💬 What We Can Discuss</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Academic programs and curriculum details</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Admission requirements and process</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>School facilities and learning environment</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Tuition fees and payment options</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Extracurricular activities and programs</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>School schedule and transportation</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Parent involvement opportunities</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>Scholarship and financial aid options</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 Ready to Get Started?</h2>\r\n\r\n        <p> \r\n            Take the first step towards your child\'s educational journey. Our experienced admissions team is ready to provide you with personalized guidance and answer all your questions.\r\n        </p>\r\n\r\n        <div class="mt-6">\r\n            <a href="/contact" class="btn btn-primary rounded text-center btn-lg">\r\n                <i class="uil uil-phone-volume me-2"></i>\r\n                Request a Callback\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 21, '2025-07-27 07:36:07', '2025-07-27 07:39:27'),
	(770, 'title', 'طلب معاودة الاتصال', 2, 'App\\Models\\Page', 21, '2025-07-27 07:39:20', '2025-07-27 07:39:20'),
	(771, 'description', 'طلب سريع وسهل للحصول على مكالمة شخصية لمناقشة القبول والبرامج والاستفسارات المدرسية.', 2, 'App\\Models\\Page', 21, '2025-07-27 07:39:20', '2025-07-27 07:39:20'),
	(772, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>طلب اتصال</h2>\r\n\r\n        <p> \r\n            نفهم أن اختيار المدرسة المناسبة لطفلك هو أحد أهم القرارات التي ستتخذها. فريق القبول المخصص لدينا هنا لمساعدتك في كل خطوة على الطريق.\r\n            <br>\r\n            سواء كان لديك أسئلة حول مناهجنا أو المرافق أو عملية القبول، أو ترغب في جدولة استشارة شخصية، نحن مستعدون لمساعدتك بجميع المعلومات التي تحتاجها لاتخاذ قرار مستنير.\r\n        </p>\r\n\r\n        <p class="mt-4">\r\n            سيتواصل معك فريقنا لمناقشة احتياجاتك المحددة والإجابة على أي أسئلة قد تكون لديك حول مدرسة السعود الدولية.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>📞 كيف يعمل</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-phone-volume"></i>\r\n                    </div>\r\n                    <h4>1. طلب اتصال</h4>\r\n                    <p class="mb-0">املأ نموذج الاستفسار ببيانات الاتصال الخاصة بك والوقت المفضل للاتصال.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-clock"></i>\r\n                    </div>\r\n                    <h4>2. سنتواصل معك</h4>\r\n                    <p class="mb-0">سيتصل بك فريق القبول لدينا خلال أقصر فترة ممكنة في الوقت المفضل لديك.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-4">\r\n                <div class="text-center">\r\n                    <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                        <i class="uil uil-comments"></i>\r\n                    </div>\r\n                    <h4>3. احصل على إجاباتك</h4>\r\n                    <p class="mb-0">ناقش أسئلتك وتعلم عن برامجنا ومرافقنا وعملية القبول.</p>\r\n                </div>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>💬 ما يمكننا مناقشته</h2>\r\n\r\n        <div class="row gy-3">\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>البرامج الأكاديمية وتفاصيل المناهج</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>متطلبات القبول والعملية</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>مرافق المدرسة وبيئة التعلم</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الرسوم الدراسية وخيارات الدفع</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n            <div class="col-xl-6">\r\n                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                    <li>\r\n                        <i class="uil uil-check"></i>\r\n                        <p>الأنشطة اللامنهجية والبرامج</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>جدول المدرسة والنقل</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>فرص مشاركة الوالدين</p>\r\n                    </li>\r\n                    <li class="mt-3">\r\n                        <i class="uil uil-check"></i>\r\n                        <p>خيارات المنح الدراسية والمساعدات المالية</p>\r\n                    </li>\r\n                </ul>\r\n            </div>\r\n            <!--/column -->\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row divider-section mt-2 mb-6">\r\n    <div class="d-flex justify-content-center align-items-center">\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n\r\n        <div class="col-2 px-0 px-lg-4">\r\n            <div class="d-flex justify-content-center">\r\n                <img class="logo" src="/assets/img/logo.png" alt="">     \r\n            </div>\r\n        </div>\r\n\r\n        <div class="col-5">\r\n            <div class="divider-line"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<div class="row">\r\n    <div class="col-12">   \r\n        <h2>🎯 مستعد للبدء؟</h2>\r\n\r\n        <p> \r\n            اتخذ الخطوة الأولى نحو رحلة طفلك التعليمية. فريق القبول ذو الخبرة لدينا مستعد لتقديم التوجيه الشخصي والإجابة على جميع أسئلتك.\r\n        </p>\r\n\r\n        <div class="mt-6">\r\n            <a href="/contact" class="btn btn-primary rounded text-center btn-lg">\r\n                <i class="uil uil-phone-volume me-2"></i>\r\n                طلب اتصال\r\n            </a>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 21, '2025-07-27 07:39:20', '2025-07-27 07:40:15'),
	(773, 'title', 'Parent Services', 1, 'App\\Models\\Page', 22, '2025-07-27 07:45:42', '2025-07-27 07:45:42'),
	(774, 'description', 'Responsive and supportive parent services ensuring clear communication, timely assistance, and a strong partnership to enhance your family’s school experience.', 1, 'App\\Models\\Page', 22, '2025-07-27 07:45:42', '2025-07-27 07:45:42'),
	(775, 'content', '<div class="row">   \r\n    <div class="col-12">   \r\n        <h2>Parent Services</h2>\r\n\r\n        <p> \r\n            At Saudi International School, we believe in fostering strong partnerships with parents through transparent communication and easy access to your child\'s educational journey. Our comprehensive parent services are designed to keep you informed and engaged in your child\'s academic progress and school activities.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>📱 ESchool - Your Digital Gateway</h2>\r\n\r\n        <p> \r\n            ESchool is our comprehensive digital platform that connects parents directly to their child\'s educational experience. This secure online portal provides real-time access to academic information, attendance records, assignments, and school communications.\r\n        </p>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="row align-items-center">\r\n                    <div class="col-lg-8">\r\n                        <h4>Access Your Child\'s Academic Journey</h4>\r\n                        <p class="mb-4">\r\n                            ESchool provides parents with instant access to grades, attendance records, homework assignments, school announcements, and direct communication with teachers. Stay connected to your child\'s educational progress anytime, anywhere.\r\n                        </p>\r\n                        \r\n                        <div class="row gy-3">\r\n                            <div class="col-xl-6">\r\n                                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                                    <li>\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>Real-time grade updates</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>Attendance tracking</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>Homework assignments</p>\r\n                                    </li>\r\n                                </ul>\r\n                            </div>\r\n                            <!--/column -->\r\n                            <div class="col-xl-6">\r\n                                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                                    <li>\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>School announcements</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>Teacher communication</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>Academic calendar</p>\r\n                                    </li>\r\n                                </ul>\r\n                            </div>\r\n                            <!--/column -->\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <div class="col-lg-4 text-center">\r\n                        <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                            <i class="uil uil-laptop"></i>\r\n                        </div>\r\n                        <h5>Secure & Accessible</h5>\r\n                        <p class="mb-4">Available 24/7 on desktop and mobile devices</p>\r\n                        \r\n                        <a href="https://eschool.sis.edu.sa/" target="_blank" class="btn btn-primary rounded text-center">\r\n                            <i class="uil uil-external-link-alt me-2"></i>\r\n                            Access ESchool\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', 1, 'App\\Models\\Page', 22, '2025-07-27 07:45:42', '2025-07-27 07:45:42'),
	(776, 'title', 'خدمات الوالدين', 2, 'App\\Models\\Page', 22, '2025-07-27 07:46:44', '2025-07-27 07:47:03'),
	(777, 'description', 'خدمات أولياء الأمور المتجاوبة والداعمة لضمان التواصل الواضح والمساعدة في الوقت المناسب والشراكة القوية لتعزيز تجربة عائلتك المدرسية.', 2, 'App\\Models\\Page', 22, '2025-07-27 07:46:44', '2025-07-27 07:47:03'),
	(778, 'content', '<div class="row">\r\n    <div class="col-12">   \r\n        <h2>خدمات الوالدين</h2>\r\n\r\n        <p> \r\n            في مدرسة السعود الدولية، نؤمن ببناء شراكات قوية مع الوالدين من خلال التواصل الشفاف والوصول السهل إلى رحلة طفلك التعليمية. تم تصميم خدمات الوالدين الشاملة لدينا لإبقائك على اطلاع ومشاركة في التقدم الأكاديمي لطفلك وأنشطة المدرسة.\r\n        </p>\r\n    </div>\r\n</div>\r\n\r\n<div class="row my-6">\r\n    <div class="col-12">   \r\n        <h2>📱 المدرسة الإلكترونية - بوابتك الرقمية</h2>\r\n\r\n        <p> \r\n            المدرسة الإلكترونية هي منصتنا الرقمية الشاملة التي تربط الوالدين مباشرة بتجربة طفلهم التعليمية. توفر هذه البوابة الآمنة عبر الإنترنت وصولاً فورياً للمعلومات الأكاديمية وسجلات الحضور والواجبات والتواصل المدرسي.\r\n        </p>\r\n\r\n        <div class="card">\r\n            <div class="card-body">\r\n                <div class="row align-items-center">\r\n                    <div class="col-lg-8">\r\n                        <h4>الوصول إلى رحلة طفلك الأكاديمية</h4>\r\n                        <p class="mb-4">\r\n                            توفر المدرسة الإلكترونية للوالدين وصولاً فورياً للدرجات وسجلات الحضور وواجبات الواجبات المنزلية والإعلانات المدرسية والتواصل المباشر مع المعلمين. ابق متصلاً بالتقدم التعليمي لطفلك في أي وقت وأي مكان.\r\n                        </p>\r\n                        \r\n                        <div class="row gy-3">\r\n                            <div class="col-xl-6">\r\n                                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                                    <li>\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>تحديثات الدرجات الفورية</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>تتبع الحضور</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>الواجبات المنزلية</p>\r\n                                    </li>\r\n                                </ul>\r\n                            </div>\r\n                            <!--/column -->\r\n                            <div class="col-xl-6">\r\n                                <ul class="icon-list bullet-bg bullet-soft-aqua mb-0">\r\n                                    <li>\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>الإعلانات المدرسية</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>التواصل مع المعلمين</p>\r\n                                    </li>\r\n                                    <li class="mt-3">\r\n                                        <i class="uil uil-check"></i>\r\n                                        <p>التقويم الأكاديمي</p>\r\n                                    </li>\r\n                                </ul>\r\n                            </div>\r\n                            <!--/column -->\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <div class="col-lg-4 text-center">\r\n                        <div class="icon btn btn-circle btn-lg btn-soft-primary disabled mb-3">\r\n                            <i class="uil uil-laptop"></i>\r\n                        </div>\r\n                        <h5>آمن ومتاح</h5>\r\n                        <p class="mb-4">متاح على مدار الساعة على أجهزة الكمبيوتر والهواتف المحمولة</p>\r\n                        \r\n                        <a href="https://eschool.sis.edu.sa/" target="_blank" class="btn btn-primary rounded text-center">\r\n                            <i class="uil uil-external-link-alt me-2"></i>\r\n                            الوصول للمدرسة الإلكترونية\r\n                        </a>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>', 2, 'App\\Models\\Page', 22, '2025-07-27 07:46:44', '2025-07-27 07:46:44'),
	(779, 'title', 'Parent Services', 1, 'App\\Models\\MenuItem', 50, '2025-07-27 07:48:19', '2025-07-27 07:48:19'),
	(780, 'title', 'Request a Call Back', 1, 'App\\Models\\MenuItem', 51, '2025-07-27 07:48:41', '2025-07-27 07:48:41'),
